import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize, SkinToneType } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Check ID Photo compliance. Output JSON. 
            Requirements: Face front-facing, eyes open, mouth closed, sufficient lighting.
            'instruction': Vietnamese command (e.g. "Mở mắt to", "Nhìn thẳng").
            If perfect: "Giữ nguyên".` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);
    // Silent fail for speed
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo using AI ONLY for Background Removal and Clothing.
 * Lighting/Beauty is now handled client-side for speed.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  // beautySettings are IGNORED here to save tokens/time, handled locally via Canvas
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- OPTIMIZED PROMPT FOR SPEED ---
  // Only focusing on Segmentation and Inpainting

  let bgInstruction = "";
  if (bgType === BackgroundType.WHITE) {
    bgInstruction = "TASK: SEGMENT PERSON ACCURATELY. REPLACE BACKGROUND WITH PURE WHITE (#FFFFFF). Handle hair strands carefully.";
  } else if (bgType === BackgroundType.BLUE) {
    bgInstruction = "TASK: SEGMENT PERSON ACCURATELY. REPLACE BACKGROUND WITH ID BLUE (#0057B7). Handle hair strands carefully.";
  } else if (bgType === BackgroundType.GRAY) {
    bgInstruction = "TASK: SEGMENT PERSON ACCURATELY. REPLACE BACKGROUND WITH NEUTRAL GRAY (#E5E7EB).";
  } else {
    // If original background, we might strictly check clothing
    bgInstruction = "Keep original background.";
  }

  let clothingInstruction = "";
  if (clothingPrompt) {
    clothingInstruction = `CLOTHING TASK: REPLACE subject's clothes with: "${clothingPrompt}". Ensure realistic fit, lighting match, and collar below chin.`;
  }

  // Combine instructions
  let prompt = `Role: Expert ID Photo Editor.
  Input: Base64 Image.

  1. ${bgInstruction}
  2. ${clothingInstruction}

  CRITICAL:
  - DO NOT change facial features (eyes, nose, mouth geometry).
  - DO NOT apply beauty filters or color grading (done client-side).
  - Output strict High Quality JPEG.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Using Flash-Image for speed
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  // processedUrl holds the result of AI operations (Background/Clothes)
  // It does NOT contain brightness/contrast changes anymore (those are applied via CSS)
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  // Before/After Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [beautySection, setBeautySection] = useState<'skin' | 'makeup' | 'light'>('light');

  // Track the last background/clothing to prevent duplicate AI calls
  const lastAiParams = useRef({
    bg: BackgroundType.ORIGINAL,
    clothing: ''
  });

  useEffect(() => {
    // Initial auto-background removal if set
    if (settings.background !== BackgroundType.ORIGINAL && processedUrl === originalImage) {
      triggerAI(settings.background, settings.clothingPrompt, "Đang xử lý lớp Phông nền...");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // --- CORE AI HANDLER (Heavy Operations Only) ---
  const triggerAI = async (
    overrideBg: BackgroundType, 
    overrideClothing: string | undefined,
    actionName: string = "Đang xử lý..."
  ) => {
    // Avoid re-triggering if parameters haven't changed (Cache Check)
    if (overrideBg === lastAiParams.current.bg && overrideClothing === lastAiParams.current.clothing) {
      return; 
    }

    setIsProcessing(true);
    setLoadingAction(actionName);

    try {
      // If returning to default state, just use original image (No AI needed)
      if (overrideBg === BackgroundType.ORIGINAL && !overrideClothing) {
        setProcessedUrl(originalImage);
        lastAiParams.current = { bg: overrideBg, clothing: '' };
      } else {
        // Call Gemini ONLY for structural changes
        const result = await processIDPhoto(originalImage, overrideBg, overrideClothing, settings.beauty, settings.size);
        setProcessedUrl(result);
        lastAiParams.current = { bg: overrideBg, clothing: overrideClothing || '' };
      }

      onUpdateSettings({ 
        ...settings, 
        background: overrideBg, 
        clothingPrompt: overrideClothing
      });

    } catch (err: any) {
      console.error(err);
      alert("Lỗi kết nối AI. Vui lòng thử lại.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  };

  // --- LOCAL HANDLERS (Instant) ---
  const handleBgChange = (bg: BackgroundType) => {
    if (bg === settings.background) return;
    triggerAI(bg, settings.clothingPrompt, "Đang thay đổi lớp Phông nền...");
  };

  const handleClothingClick = (prompt: string) => {
    if (prompt === settings.clothingPrompt) return;
    triggerAI(settings.background, prompt, prompt ? "Đang thay thế lớp Trang phục..." : "Đang hoàn tác lớp Trang phục...");
  };

  // Instant Client-Side Update for Sliders
  const handleBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
    // NO API CALL HERE - Pure React State Update
  };

  // Calculate CSS Filters based on settings
  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType, smoothSkin } = settings.beauty;

    // Lighting: -50 to 50 maps to brightness 50% to 150%
    const brightnessVal = 100 + (lighting * 1.5); 
    // Contrast: -50 to 50 maps to contrast 50% to 150%
    const contrastVal = 100 + (contrast * 1.5);

    // Simple warm/cool simulation using sepia/hue-rotate for skin tone
    let sepia = 0;
    let hue = 0;
    let saturate = 100;

    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) {
            sepia = skinToneIntensity * 0.3; // Bronze look
            saturate = 100 - (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.ROSY) {
            sepia = skinToneIntensity * 0.1;
            hue = -10; // Slight pink shift
            saturate = 100 + (skinToneIntensity * 0.2);
        } else if (skinToneType === SkinToneType.FAIR) {
            brightnessVal + (skinToneIntensity * 0.1);
            saturate = 100 - (skinToneIntensity * 0.2);
        }
    }

    // Blur for smooth skin (Basic implementation)
    const blurPx = smoothSkin * 0.3; 

    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg) blur(${blurPx}px)`;
  }, [settings.beauty]);

  // Mouse/Touch handlers for slider
  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingRef.current || !imageContainerRef.current) return;
    const rect = imageContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  // Final Export: Bake the CSS filters into the Canvas
  const handleFinish = () => {
    setIsProcessing(true);
    setLoadingAction("Đang áp dụng bộ lọc...");

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = new Image();

    img.src = processedUrl; // Use the AI-segmented image as base
    img.crossOrigin = "anonymous";

    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;

      if (ctx) {
        // 1. Draw image with CSS filters applied via Context
        ctx.filter = imageFilters;
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

        // 2. Export
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
      setIsProcessing(false);
    };
  };

  // Filter clothing options
  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);

  const SkinToneOptions = [
    { id: SkinToneType.NATURAL, label: 'Tự nhiên', color: '#e5cba6' },
    { id: SkinToneType.FAIR, label: 'Trắng Sáng', color: '#fcebe3' },
    { id: SkinToneType.ROSY, label: 'Trắng Hồng', color: '#ffdee8' },
    { id: SkinToneType.TAN, label: 'Ngăm Khỏe', color: '#cd9b75' },
  ];

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
      onMouseMove={handleMouseMove}
      onTouchMove={handleMouseMove}
      onMouseUp={() => { isDraggingRef.current = false; }}
      onTouchEnd={() => { isDraggingRef.current = false; }}
    >

      {/* LEFT: Sidebar / Controls */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        {/* Header */}
        <div className="p-5 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">⚡</span> Chỉnh sửa
          </h2>
          <div className="flex flex-col items-end">
            <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Fast Mode</span>
          </div>
        </div>

        {/* SEGMENTED CONTROL TABS */}
        <div className="px-5 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl">
            {(['background', 'beauty', 'clothing'] as EditorTab[]).map((tab) => (
               <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`flex-1 py-3 text-xs font-bold uppercase tracking-wide rounded-lg transition-all duration-200 ${
                  activeTab === tab 
                    ? 'bg-white text-brand-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {tab === 'background' ? 'Phông nền' : tab === 'beauty' ? 'Màu sắc' : 'Trang phục'}
              </button>
            ))}
          </div>
        </div>

        {/* SCROLLABLE CONTENT */}
        <div className="flex-1 overflow-y-auto p-5 bg-white scrollbar-hide">

          {/* --- BACKGROUND TAB (USES AI) --- */}
          {activeTab === 'background' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="bg-blue-50 border border-blue-200 p-3 rounded-lg text-xs text-blue-700 mb-2">
                  ℹ️ Tính năng này sử dụng AI để tách nền.
              </div>
              <div className="grid grid-cols-2 gap-4">
                 {config.backgroundConfig.map(bg => (
                   <button 
                      key={bg.type}
                      onClick={() => handleBgChange(bg.type)} 
                      disabled={isProcessing}
                      className={`relative h-32 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all group ${
                        settings.background === bg.type 
                          ? 'border-brand-500 bg-brand-50 shadow-md ring-1 ring-brand-200' 
                          : 'border-slate-100 hover:border-brand-200 hover:bg-slate-50'
                      }`}
                    >
                      <div className="w-12 h-12 rounded-full shadow-inner" style={{ backgroundColor: bg.hexColor }}></div>
                      <span className={`text-xs font-bold ${settings.background === bg.type ? 'text-brand-700' : 'text-gray-600'}`}>{bg.label}</span>
                    </button>
                ))}

                {/* Original */}
                <button 
                  onClick={() => handleBgChange(BackgroundType.ORIGINAL)} 
                  disabled={isProcessing}
                  className={`relative h-32 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all group ${
                    settings.background === BackgroundType.ORIGINAL
                      ? 'border-brand-500 bg-brand-50 shadow-md ring-1 ring-brand-200' 
                      : 'border-slate-100 hover:border-brand-200 hover:bg-slate-50'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full shadow-inner bg-gray-300 flex items-center justify-center">📷</div>
                  <span className="text-xs font-bold text-gray-600">Ảnh Gốc</span>
                </button>
              </div>
            </div>
          )}

          {/* --- BEAUTY TAB (LOCAL CSS) --- */}
          {activeTab === 'beauty' && (
            <div className="space-y-4 animate-fadeIn">

              <div className="bg-green-50/50 p-3 rounded-xl border border-green-100 mb-2">
                <p className="text-[11px] text-green-700 font-medium flex gap-2">
                  <svg className="w-4 h-4 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                  Chế độ xử lý tức thì (Không dùng AI)
                </p>
              </div>

              {/* SECTION: LIGHTING */}
              <div className="border border-gray-100 rounded-xl overflow-hidden">
                <button 
                  onClick={() => setBeautySection('light')}
                  className={`w-full p-3 flex justify-between items-center text-sm font-bold ${beautySection === 'light' ? 'bg-yellow-50 text-yellow-700' : 'bg-white text-gray-700 hover:bg-gray-50'}`}
                >
                  <span className="flex items-center gap-2">💡 Ánh sáng & Tương phản</span>
                  <svg className={`w-4 h-4 transition-transform ${beautySection === 'light' ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                </button>

                {beautySection === 'light' && (
                  <div className="p-4 bg-white space-y-5 animate-fadeIn">
                     {/* Brightness */}
                     <div className="group">
                        <div className="flex justify-between text-xs font-bold text-gray-700 mb-2">
                          <span>Độ sáng</span>
                          <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px]">{settings.beauty.lighting > 0 ? '+' : ''}{settings.beauty.lighting}</span>
                        </div>
                        <input 
                          type="range" min="-50" max="50" step="5"
                          value={settings.beauty.lighting} 
                          onChange={(e) => handleBeautyChange('lighting', Number(e.target.value))} 
                          className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-yellow-500" 
                        />
                     </div>

                     {/* Contrast */}
                     <div className="group">
                        <div className="flex justify-between text-xs font-bold text-gray-700 mb-2">
                          <span>Độ tương phản</span>
                          <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px]">{settings.beauty.contrast > 0 ? '+' : ''}{settings.beauty.contrast}</span>
                        </div>
                        <input 
                          type="range" min="-50" max="50" step="5"
                          value={settings.beauty.contrast} 
                          onChange={(e) => handleBeautyChange('contrast', Number(e.target.value))} 
                          className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-gray-600" 
                        />
                     </div>
                  </div>
                )}
              </div>

              {/* SECTION: SKIN & TONE */}
              <div className="border border-gray-100 rounded-xl overflow-hidden">
                <button 
                  onClick={() => setBeautySection('skin')}
                  className={`w-full p-3 flex justify-between items-center text-sm font-bold ${beautySection === 'skin' ? 'bg-brand-50 text-brand-700' : 'bg-white text-gray-700 hover:bg-gray-50'}`}
                >
                  <span className="flex items-center gap-2">✨ Tông màu & Da</span>
                  <svg className={`w-4 h-4 transition-transform ${beautySection === 'skin' ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                </button>

                {beautySection === 'skin' && (
                  <div className="p-4 bg-white space-y-5 animate-fadeIn">
                     {/* Skin Tone Selector */}
                     <div>
                       <label className="text-xs font-bold text-gray-500 mb-2 block">Tông màu ảnh</label>
                       <div className="grid grid-cols-4 gap-2 mb-3">
                          {SkinToneOptions.map(tone => (
                            <button
                              key={tone.id}
                              onClick={() => {
                                handleBeautyChange('skinToneType', tone.id);
                                if (settings.beauty.skinToneIntensity === 0) handleBeautyChange('skinToneIntensity', 30);
                              }}
                              className={`flex flex-col items-center gap-1 p-2 rounded-lg border transition-all ${
                                settings.beauty.skinToneType === tone.id 
                                ? 'border-brand-500 bg-brand-50' 
                                : 'border-gray-100 hover:bg-gray-50'
                              }`}
                            >
                              <div className="w-6 h-6 rounded-full border shadow-sm" style={{ backgroundColor: tone.color }}></div>
                              <span className="text-[9px] font-bold text-gray-600">{tone.label}</span>
                            </button>
                          ))}
                       </div>

                       <input 
                          type="range" min="0" max="100" step="10"
                          value={settings.beauty.skinToneIntensity} 
                          onChange={(e) => handleBeautyChange('skinToneIntensity', Number(e.target.value))} 
                          className="w-full h-2 bg-amber-100 rounded-lg appearance-none cursor-pointer accent-amber-600" 
                        />
                     </div>

                     <hr className="border-gray-100" />

                     {/* Smooth Skin (Blur) */}
                     <div>
                       <div className="flex justify-between text-xs font-bold text-gray-700 mb-1">
                         <span>Làm mịn (Soft Focus)</span>
                       </div>
                       <input 
                        type="range" min="0" max="5" step="1" 
                        value={settings.beauty.smoothSkin} 
                        onChange={(e) => handleBeautyChange('smoothSkin', Number(e.target.value))} 
                        className="w-full h-2 bg-brand-200 rounded-lg appearance-none cursor-pointer accent-brand-600" 
                       />
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* --- CLOTHING TAB (USES AI) --- */}
          {activeTab === 'clothing' && (
            <div className="animate-fadeIn">
               <div className="bg-blue-50 border border-blue-200 p-3 rounded-lg text-xs text-blue-700 mb-4">
                  ℹ️ Tính năng này sử dụng AI để thay trang phục.
              </div>
              <div className="flex p-1 bg-gray-100 rounded-xl mb-4">
                <button onClick={() => setGenderTab('male')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${genderTab === 'male' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'}`}>Nam</button>
                <button onClick={() => setGenderTab('female')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${genderTab === 'female' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'}`}>Nữ</button>
              </div>
              <div className="grid grid-cols-2 gap-3 mb-4">
                <button onClick={() => handleClothingClick('')} className={`p-3 border-2 rounded-xl text-left transition-all ${!settings.clothingPrompt ? 'border-green-500 bg-green-50 shadow-md' : 'border-gray-100 hover:border-gray-300'}`}>
                   <div className="text-2xl mb-2">👕</div>
                   <div className="text-xs font-bold text-gray-800">Trang phục gốc</div>
                </button>
                {activeClothingOptions.map((item) => (
                  <button 
                    key={item.id} 
                    onClick={() => handleClothingClick(item.prompt)} 
                    disabled={isProcessing}
                    className={`p-3 border-2 rounded-xl text-left transition-all group relative ${
                      settings.clothingPrompt === item.prompt 
                        ? `bg-white ${item.color} shadow-md` 
                        : 'bg-white border-gray-100 hover:border-gray-300'
                    }`}
                  >
                    <div className="text-2xl mb-2">{item.icon}</div>
                    <div className="text-xs font-bold text-gray-700">{item.label}</div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-5 border-t border-gray-200 bg-white space-y-3 z-30">
           <button 
            onClick={handleFinish} 
            disabled={isProcessing} 
            className={`w-full py-4 rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 transition-all transform active:scale-95 ${
              isProcessing 
                ? 'bg-gray-100 text-gray-400 cursor-wait' 
                : 'bg-brand-600 hover:bg-brand-700 text-white hover:shadow-xl'
            }`}
          >
            {isProcessing ? 'Đang xử lý...' : 'Hoàn tất & In Ảnh'}
          </button>

          <button 
            onClick={onRetake} 
            disabled={isProcessing}
