import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize, SkinToneType } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Check ID Photo compliance. Output JSON. 
            Requirements: Face front-facing, eyes open, mouth closed, sufficient lighting.
            'instruction': Vietnamese command (e.g. "Mở mắt to", "Nhìn thẳng").
            If perfect: "Giữ nguyên".` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo using AI.
 * Handles Background, Clothing, AND AI-based Beauty (Retouching/Makeup).
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- 1. BACKGROUND PROMPT ---
  let bgInstruction = "";
  if (bgType === BackgroundType.WHITE) {
    bgInstruction = "TASK 1: SEGMENT PERSON. CHANGE BACKGROUND TO PURE WHITE (#FFFFFF). Keep hair details.";
  } else if (bgType === BackgroundType.BLUE) {
    bgInstruction = "TASK 1: SEGMENT PERSON. CHANGE BACKGROUND TO ID PHOTO BLUE (#0057B7). Keep hair details.";
  } else if (bgType === BackgroundType.GRAY) {
    bgInstruction = "TASK 1: SEGMENT PERSON. CHANGE BACKGROUND TO NEUTRAL GRAY (#E5E7EB).";
  } else {
    bgInstruction = "TASK 1: Keep original background.";
  }

  // --- 2. CLOTHING PROMPT ---
  let clothingInstruction = "TASK 2: Keep original clothing.";
  if (clothingPrompt) {
    clothingInstruction = `TASK 2: CHANGE CLOTHING to: "${clothingPrompt}". Fit naturally to neck/shoulders. High realism.`;
  }

  // --- 3. BEAUTY / RETOUCH PROMPT ---
  // Only add these if user requested, to avoid hallucinations
  let beautyInstruction = "TASK 3: PRESERVE FACIAL IDENTITY 100%.";
  const retouchSteps = [];

  if (beautySettings.removeBlemishes) {
    retouchSteps.push("Remove all acne, moles, scars, and blemishes from skin.");
  }

  if (beautySettings.smoothSkin > 10) {
    retouchSteps.push(`Smooth skin texture (intensity ${beautySettings.smoothSkin}%).`);
  }

  // Makeup
  if (beautySettings.lipstickIntensity > 10) {
    retouchSteps.push(`Apply ${beautySettings.lipstickColor} lipstick (opacity ${beautySettings.lipstickIntensity}%).`);
  }

  if (beautySettings.blushIntensity > 10) {
    retouchSteps.push(`Apply soft blush to cheeks (opacity ${beautySettings.blushIntensity}%).`);
  }

  if (retouchSteps.length > 0) {
    beautyInstruction = `TASK 3: RETOUCHING. ${retouchSteps.join(" ")} Maintain natural skin texture.`;
  }

  // Combine Prompt
  let prompt = `Role: Professional ID Photo Editor.
  Input: Image of a person.

  ${bgInstruction}
  ${clothingInstruction}
  ${beautyInstruction}

  CRITICAL RULES:
  - Do not change facial structure/geometry (eyes/nose/mouth shape).
  - Do not adjust global lighting (Client handles brightness).
  - Output: High Quality JPEG image only.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Fast model
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  // processedUrl holds the result of AI operations (Background/Clothes/Makeup)
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  // Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');

  // Timeout ref for debouncing AI calls on sliders
  const debounceRef = useRef<NodeJS.Timeout | null>(null);

  // Track parameters to prevent duplicate AI calls
  const lastAiParams = useRef({
    bg: BackgroundType.ORIGINAL,
    clothing: '',
    beautyHash: '' // Simple hash string to track beauty changes
  });

  // Generate a hash string for heavy beauty settings (excluding client-side ones like lighting)
  const getBeautyHash = (b: typeof settings.beauty) => {
    return `${b.removeBlemishes}-${b.lipstickColor}-${b.lipstickIntensity}-${b.blushIntensity}-${b.smoothSkin}`;
  };

  useEffect(() => {
    // Initial AI call if settings are pre-configured
    const currentHash = getBeautyHash(settings.beauty);
    if (
      (settings.background !== BackgroundType.ORIGINAL || settings.clothingPrompt || currentHash !== getBeautyHash({ ...settings.beauty, removeBlemishes: false, lipstickIntensity: 0, blushIntensity: 0, smoothSkin: 0 })) 
      && processedUrl === originalImage
    ) {
      triggerAI(settings.background, settings.clothingPrompt, settings.beauty, "Đang xử lý ảnh...");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // --- AI HANDLER ---
  const triggerAI = async (
    overrideBg: BackgroundType, 
    overrideClothing: string | undefined,
    overrideBeauty: typeof settings.beauty,
    actionName: string = "Đang xử lý..."
  ) => {
    const newHash = getBeautyHash(overrideBeauty);

    // Check Cache
    if (
      overrideBg === lastAiParams.current.bg && 
      overrideClothing === lastAiParams.current.clothing &&
      newHash === lastAiParams.current.beautyHash
    ) {
      return; 
    }

    setIsProcessing(true);
    setLoadingAction(actionName);

    try {
      // Logic: If everything is default, show original. Else, call AI.
      const isDefault = overrideBg === BackgroundType.ORIGINAL && !overrideClothing && !overrideBeauty.removeBlemishes && overrideBeauty.lipstickIntensity === 0 && overrideBeauty.blushIntensity === 0 && overrideBeauty.smoothSkin === 0;

      if (isDefault) {
        setProcessedUrl(originalImage);
        lastAiParams.current = { bg: overrideBg, clothing: '', beautyHash: newHash };
      } else {
        const result = await processIDPhoto(originalImage, overrideBg, overrideClothing, overrideBeauty, settings.size);
        setProcessedUrl(result);
        lastAiParams.current = { bg: overrideBg, clothing: overrideClothing || '', beautyHash: newHash };
      }

      onUpdateSettings({ 
        ...settings, 
        background: overrideBg, 
        clothingPrompt: overrideClothing,
        beauty: overrideBeauty
      });

    } catch (err: any) {
      console.error(err);
      alert("Lỗi xử lý AI. Vui lòng thử lại.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => {
    triggerAI(bg, settings.clothingPrompt, settings.beauty, "Đang thay đổi nền...");
  };

  const handleClothingClick = (prompt: string) => {
    triggerAI(settings.background, prompt, settings.beauty, "Đang thay trang phục...");
  };

  // Instant Client-Side Update (Lighting/Color)
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  // Debounced AI Update (Makeup/Blemishes)
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    // 1. Update UI immediately
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });

    // 2. Debounce AI call (Wait 800ms after last slide)
    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      triggerAI(settings.background, settings.clothingPrompt, newBeauty, "Đang áp dụng làm đẹp...");
    }, 800);
  };

  const handleBlemishToggle = () => {
      const newVal = !settings.beauty.removeBlemishes;
      const newBeauty = { ...settings.beauty, removeBlemishes: newVal };
      triggerAI(settings.background, settings.clothingPrompt, newBeauty, newVal ? "Đang xóa mụn..." : "Đang khôi phục...");
  };

  // --- CSS FILTER GENERATOR ---
  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);

    let sepia = 0;
    let hue = 0;
    let saturate = 100;

    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) {
            sepia = skinToneIntensity * 0.3; 
            saturate = 100 - (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.ROSY) {
            sepia = skinToneIntensity * 0.15;
            hue = -10; 
            saturate = 100 + (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.FAIR) {
            saturate = 100 - (skinToneIntensity * 0.1);
        }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  // --- FINAL EXPORT ---
  const handleFinish = () => {
    setIsProcessing(true);
    setLoadingAction("Đang xuất ảnh...");

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";

    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      if (ctx) {
        ctx.filter = imageFilters;
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
      setIsProcessing(false);
    };
  };

  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);
  const SkinToneOptions = [
    { id: SkinToneType.NATURAL, label: 'Tự nhiên', color: '#e5cba6' },
    { id: SkinToneType.FAIR, label: 'Trắng Sáng', color: '#fcebe3' },
    { id: SkinToneType.ROSY, label: 'Trắng Hồng', color: '#ffdee8' },
    { id: SkinToneType.TAN, label: 'Ngăm Khỏe', color: '#cd9b75' },
  ];

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      {/* Sidebar */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">⚡</span> Chỉnh sửa
          </h2>
          <div className="flex flex-col items-end">
            <span className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full">AI Pro Mode</span>
          </div>
        </div>

        <div className="px-4 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl overflow-x-auto no-scrollbar">
            {[
              {id: 'background', label: 'Phông nền'},
              {id: 'beauty', label: 'Màu da'},
              {id: 'makeup', label: 'Trang điểm'}, // NEW TAB
              {id: 'clothing', label: 'Trang phục'}
            ].map((tab) => (
               <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
