                 <div className="flex justify-between text-xs font-bold text-gray-600 mb-2">
                    <span>Má hồng</span>
                    <span>{settings.beauty.blushIntensity}%</span>
                  </div>
                  <input type="range" min="0" max="100" step="20" value={settings.beauty.blushIntensity} onChange={(e) => handleAiBeautyChange('blushIntensity', Number(e.target.value))} className="w-full h-2 bg-red-100 rounded-lg appearance-none cursor-pointer accent-red-400" />
              </div>
            </div>
          )}

          {/* CLOTHING TAB */}
          {activeTab === 'clothing' && (
            <div className="animate-fadeIn">
               <div className="bg-blue-50 border border-blue-200 p-3 rounded-lg text-xs text-blue-700 mb-4 flex gap-2">
                  <span>🤖</span> Dùng AI để thay áo.
              </div>
              <div className="flex p-1 bg-gray-100 rounded-xl mb-4">
                <button onClick={() => setGenderTab('male')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${genderTab === 'male' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'}`}>Nam</button>
                <button onClick={() => setGenderTab('female')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${genderTab === 'female' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'}`}>Nữ</button>
              </div>
              <div className="grid grid-cols-2 gap-3 mb-4">
                <button onClick={() => handleClothingClick('')} className={`p-3 border-2 rounded-xl text-left transition-all ${!settings.clothingPrompt ? 'border-green-500 bg-green-50 shadow-md' : 'border-gray-100 hover:border-gray-300'}`}>
                   <div className="text-2xl mb-2">👕</div>
                   <div className="text-xs font-bold text-gray-800">Trang phục gốc</div>
                </button>
                {activeClothingOptions.map((item) => (
                  <button 
                    key={item.id} 
                    onClick={() => handleClothingClick(item.prompt)} 
                    disabled={isProcessing}
                    className={`p-3 border-2 rounded-xl text-left transition-all group relative ${
                      settings.clothingPrompt === item.prompt 
                        ? `bg-white ${item.color} shadow-md` 
                        : 'bg-white border-gray-100 hover:border-gray-300'
                    }`}
                  >
                    <div className="text-2xl mb-2">{item.icon}</div>
                    <div className="text-xs font-bold text-gray-700">{item.label}</div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-200 bg-white space-y-3 z-30">
           <button 
            onClick={handleFinish} 
            disabled={isProcessing} 
            className={`w-full py-4 rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 transition-all transform active:scale-95 ${
              isProcessing 
                ? 'bg-gray-100 text-gray-400 cursor-wait' 
                : 'bg-brand-600 hover:bg-brand-700 text-white hover:shadow-xl'
            }`}
          >
            {isProcessing ? 'Đang xử lý AI...' : 'Hoàn tất & In Ảnh'}
          </button>

          <button 
            onClick={onRetake} 
            disabled={isProcessing}
            className="w-full py-3 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold hover:bg-slate-50 hover:text-red-500 transition"
          >
            Chụp lại
          </button>
        </div>
      </div>

      {/* Preview Area */}
      <div className="flex-1 bg-slate-100 relative flex flex-col items-center justify-center p-6"
           onMouseMove={(e) => {
             if (isDraggingRef.current && imageContainerRef.current) {
                const rect = imageContainerRef.current.getBoundingClientRect();
                const clientX = 'touches' in e ? (e as any).touches[0].clientX : (e as any).clientX;
                const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
                setSliderPosition((x / rect.width) * 100);
             }
           }}
           onTouchMove={(e) => {
             if (isDraggingRef.current && imageContainerRef.current) {
                const rect = imageContainerRef.current.getBoundingClientRect();
                const clientX = e.touches[0].clientX;
                const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
                setSliderPosition((x / rect.width) * 100);
             }
           }}
      >
        <div className="absolute top-4 z-10 bg-white/90 backdrop-blur text-slate-600 px-5 py-2.5 rounded-full text-xs font-bold border border-white shadow-sm flex items-center gap-2 select-none animate-fadeIn">
          <svg className="w-4 h-4 text-brand-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"></path></svg>
          So sánh Trước / Sau
        </div>

        <div 
          ref={imageContainerRef}
          className="relative shadow-2xl bg-white select-none cursor-ew-resize overflow-hidden rounded-sm border-4 border-brand-200" 
          style={{ 
             maxHeight: '85vh', 
             aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3',
             height: '85vh' 
          }}
          onMouseDown={() => { isDraggingRef.current = true; }}
          onTouchStart={() => { isDraggingRef.current = true; }}
        >
          {isProcessing && (
            <div className="absolute inset-0 z-30 bg-black/40 flex flex-col items-center justify-center backdrop-blur-[2px]">
               <div className="bg-white p-6 rounded-2xl shadow-2xl flex flex-col items-center animate-bounce-in">
                 <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
                 <p className="text-brand-800 font-bold text-sm">{loadingAction}</p>
                 <p className="text-[10px] text-gray-400 mt-1">Gemini AI Processor ⚡</p>
               </div>
            </div>
          )}

          <img 
            src={processedUrl} 
            alt="After" 
            className="absolute inset-0 w-full h-full object-contain pointer-events-none bg-white transition-all duration-100"
            style={{ filter: imageFilters }}
          />

          <div 
            className="absolute inset-0 w-full h-full overflow-hidden border-r-2 border-white pointer-events-none bg-white"
            style={{ width: `${sliderPosition}%` }}
          >
             <img 
              src={originalImage} 
              alt="Before" 
              className="absolute inset-0 w-full h-full object-contain max-w-none" 
            />

            <div className="absolute top-1/2 right-0 transform translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-xl flex items-center justify-center z-20 cursor-ew-resize hover:scale-110 transition-transform border border-gray-100">
              <svg className="w-5 h-5 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8 9l4-4 4 4m0 6l-4 4-4-4"></path></svg>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ImageEditor;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  // processedUrl holds the result of AI operations (Background/Clothes/Makeup)
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  // Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');

  // Timeout ref for debouncing AI calls on sliders
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Track parameters to prevent duplicate AI calls
  const lastAiParams = useRef({
    bg: BackgroundType.ORIGINAL,
    clothing: '',
    beautyHash: '' // Simple hash string to track beauty changes
  });

  // Generate a hash string for heavy beauty settings (excluding client-side ones like lighting)
  const getBeautyHash = (b: typeof settings.beauty) => {
    return `${b.removeBlemishes}-${b.lipstickColor}-${b.lipstickIntensity}-${b.blushIntensity}-${b.smoothSkin}`;
  };

  useEffect(() => {
    // Initial AI call if settings are pre-configured
    const currentHash = getBeautyHash(settings.beauty);
    if (
      (settings.background !== BackgroundType.ORIGINAL || settings.clothingPrompt || currentHash !== getBeautyHash({ ...settings.beauty, removeBlemishes: false, lipstickIntensity: 0, blushIntensity: 0, smoothSkin: 0 })) 
      && processedUrl === originalImage
    ) {
      triggerAI(settings.background, settings.clothingPrompt, settings.beauty, "Đang xử lý ảnh...");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // --- AI HANDLER ---
  const triggerAI = async (
    overrideBg: BackgroundType, 
    overrideClothing: string | undefined,
    overrideBeauty: typeof settings.beauty,
    actionName: string = "Đang xử lý..."
  ) => {
    const newHash = getBeautyHash(overrideBeauty);

    // Check Cache
    if (
      overrideBg === lastAiParams.current.bg && 
      overrideClothing === lastAiParams.current.clothing &&
      newHash === lastAiParams.current.beautyHash
    ) {
      return; 
    }

    setIsProcessing(true);
    setLoadingAction(actionName);

    try {
      // Logic: If everything is default, show original. Else, call AI.
      const isDefault = overrideBg === BackgroundType.ORIGINAL && !overrideClothing && !overrideBeauty.removeBlemishes && overrideBeauty.lipstickIntensity === 0 && overrideBeauty.blushIntensity === 0 && overrideBeauty.smoothSkin === 0;

      if (isDefault) {
        setProcessedUrl(originalImage);
        lastAiParams.current = { bg: overrideBg, clothing: '', beautyHash: newHash };
      } else {
        const result = await processIDPhoto(originalImage, overrideBg, overrideClothing, overrideBeauty, settings.size);
        setProcessedUrl(result);
        lastAiParams.current = { bg: overrideBg, clothing: overrideClothing || '', beautyHash: newHash };
      }

      onUpdateSettings({ 
        ...settings, 
        background: overrideBg, 
        clothingPrompt: overrideClothing,
        beauty: overrideBeauty
      });

    } catch (err: any) {
      console.error(err);
      alert("Lỗi xử lý AI. Vui lòng thử lại.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => {
    triggerAI(bg, settings.clothingPrompt, settings.beauty, "Đang thay đổi nền...");
  };

  const handleClothingClick = (prompt: string) => {
    triggerAI(settings.background, prompt, settings.beauty, "Đang thay trang phục...");
  };

  // Instant Client-Side Update (Lighting/Color)
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  // Debounced AI Update (Makeup/Blemishes)
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    // 1. Update UI immediately
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });

    // 2. Debounce AI call (Wait 800ms after last slide)
    if (debounceRef.current) clearTimeout(debounceRef.current);

    debounceRef.current = setTimeout(() => {
      triggerAI(settings.background, settings.clothingPrompt, newBeauty, "Đang áp dụng làm đẹp...");
    }, 800);
  };

  const handleBlemishToggle = () => {
      const newVal = !settings.beauty.removeBlemishes;
      const newBeauty = { ...settings.beauty, removeBlemishes: newVal };
      triggerAI(settings.background, settings.clothingPrompt, newBeauty, newVal ? "Đang xóa mụn..." : "Đang khôi phục...");
  };

  // --- CSS FILTER GENERATOR ---
  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);

    let sepia = 0;
    let hue = 0;
    let saturate = 100;

    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) {
            sepia = skinToneIntensity * 0.3; 
            saturate = 100 - (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.ROSY) {
            sepia = skinToneIntensity * 0.15;
            hue = -10; 
            saturate = 100 + (skinToneIntensity * 0.1);
        } else if (skinToneType === SkinToneType.FAIR) {
            saturate = 100 - (skinToneIntensity * 0.1);
        }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  // --- FINAL EXPORT ---
  const handleFinish = () => {
    setIsProcessing(true);
    setLoadingAction("Đang xuất ảnh...");

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";

    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      if (ctx) {
        ctx.filter = imageFilters;
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
      setIsProcessing(false);
    };
  };

  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);
  const SkinToneOptions = [
