// --- CẤU HÌNH GOOGLE APPS SCRIPT ---
// URL sẽ được lấy từ Config Service do người dùng nhập trong Admin Panel
const getScriptUrl = () => {
    const config = getConfig();
    return config.googleScriptUrl || '';
};

/**
 * Lưu ảnh lên Google Drive & Sheets thông qua Google Apps Script Web App.
 */
export const savePhotoToCloud = async (photo: SavedPhoto): Promise<string | null> => {
  const url = getScriptUrl();
  if (!url) {
    alert("Vui lòng cấu hình 'Google Apps Script URL' trong trang Admin để sử dụng tính năng lưu trữ.");
    return null;
  }

  try {
    // Chuẩn bị payload
    const payload = {
        action: 'save',
        dataUrl: photo.dataUrl,
        timestamp: photo.timestamp,
        settings: photo.settings
    };

    // Gọi đến Google Script Web App
    // Lưu ý: Sử dụng method POST và mode 'no-cors' thường được dùng cho form submission,
    // NHƯNG để nhận lại phản hồi ID, Apps Script cần trả về ContentService.createTextOutput
    // và chúng ta sử dụng fetch bình thường. Redirect sẽ được browser tự xử lý.

    // Do cơ chế CORS của Google, cách tốt nhất là dùng POST với text/plain để tránh preflight
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify(payload),
      headers: {
          'Content-Type': 'text/plain;charset=utf-8', 
      }
    });

    const result = await response.json();

    if (result.success && result.id) {
        return result.id;
    } else {
        console.error("Lỗi từ Google Script:", result);
        return null;
    }

  } catch (error: any) {
    console.error("Lỗi lưu trữ:", error);
    alert("Không thể kết nối đến Google Script. Vui lòng kiểm tra URL và quyền truy cập (Anyone).");
    return null;
  }
};

/**
 * Lấy ảnh từ Google Drive/Sheet bằng ID
 */
export const getPhotoById = async (id: string): Promise<SavedPhoto | null> => {
  const url = getScriptUrl();
  if (!url) return null;

  try {
    // Gọi GET với tham số action=get&id=...
    // Apps Script phải xử lý doGet()
    const fetchUrl = `${url}?action=get&id=${id}`;

    const response = await fetch(fetchUrl);
    const result = await response.json();

    if (result && result.id) {
        return result as SavedPhoto;
    }

    return null;

  } catch (error) {
    console.error("Lỗi lấy ảnh:", error);
    return null;
  }
};

