import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize, SkinToneType } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Check ID Photo compliance. Output JSON. 
            Requirements: Face front-facing, eyes open, mouth closed, sufficient lighting.
            'instruction': Vietnamese command (e.g. "Mở mắt to", "Nhìn thẳng").
            If perfect: "Giữ nguyên".` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);

    // CHECK FOR QUOTA EXHAUSTED (429)
    // The error object structure varies, so we check multiple properties
    if (
      error.status === 429 || 
      error.status === 'RESOURCE_EXHAUSTED' || 
      (error.message && error.message.includes('429')) ||
      (error.error && error.error.code === 429)
    ) {
       return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Hết lượt AI. Chuyển thủ công.', 
        faceDetected: true 
      };
    }

    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo using AI in a SINGLE BATCH.
 * Strictly preserves biometrics.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- 1. BACKGROUND PROMPT ---
  let bgInstruction = "";
  if (bgType === BackgroundType.WHITE) {
    bgInstruction = "TASK 1 (Background): Segment person precisely. Replace background with solid #FFFFFF. Handle hair strands naturally.";
  } else if (bgType === BackgroundType.BLUE) {
    bgInstruction = "TASK 1 (Background): Segment person precisely. Replace background with ID Blue #0057B7. Handle hair strands naturally.";
  } else if (bgType === BackgroundType.GRAY) {
    bgInstruction = "TASK 1 (Background): Segment person precisely. Replace background with Neutral Gray #E5E7EB.";
  } else {
    bgInstruction = "TASK 1 (Background): Keep original background.";
  }

  // --- 2. CLOTHING PROMPT ---
  let clothingInstruction = "TASK 2 (Clothing): Keep original clothing.";
  if (clothingPrompt) {
    clothingInstruction = `TASK 2 (Clothing): Replace outfit with: "${clothingPrompt}". 
    - Ensure the collar fits the neck perfectly. 
    - Adjust lighting on clothes to match the face.
    - Style: Professional ID Photo.`;
  }

  // --- 3. BEAUTY / RETOUCH PROMPT (Subtle) ---
  let beautyInstruction = "TASK 3 (Retouch): No makeup changes.";
  const retouchSteps = [];

  // Blemishes
  if (beautySettings.removeBlemishes) {
    retouchSteps.push("Subtly remove temporary acne/blemishes. KEEP MOLES (nốt ruồi) AND SCARS (sẹo) as they are biometric identifiers.");
  }

  // Smooth Skin
  if (beautySettings.smoothSkin > 0) {
    const strength = beautySettings.smoothSkin > 50 ? "moderate" : "very subtle";
    retouchSteps.push(`Apply ${strength} skin smoothing. Retain skin texture pores.`);
  }

  // Makeup: Lipstick
  if (beautySettings.lipstickIntensity > 0) {
    retouchSteps.push(`Apply ${beautySettings.lipstickColor} lipstick (opacity ${beautySettings.lipstickIntensity}%).`);
  }

  // Makeup: Blush
  if (beautySettings.blushIntensity > 0) {
    retouchSteps.push(`Apply soft blush (opacity ${beautySettings.blushIntensity}%).`);
  }

  // Makeup: Eyebrows (New)
  if (beautySettings.eyebrowIntensity > 0) {
    retouchSteps.push(`Define and darken eyebrows naturally (intensity ${beautySettings.eyebrowIntensity}%). Keep original shape.`);
  }

  // Makeup: Contour (New)
  if (beautySettings.contourIntensity > 0) {
    retouchSteps.push(`Apply soft facial contouring/shading to define jawline and nose bridge (intensity ${beautySettings.contourIntensity}%). Blend perfectly.`);
  }

  // Hair (New)
  if (beautySettings.hairVolume > 0) {
    retouchSteps.push(`Fix hair gaps, fill in receding hairline slightly, and fix flyaways (neatness level ${beautySettings.hairVolume}%). Keep original hairstyle.`);
  }

  if (retouchSteps.length > 0) {
    beautyInstruction = `TASK 3 (Retouch): ${retouchSteps.join(" ")}`;
  }

  // Combine Prompt
  let prompt = `Role: Expert ID Photo Editor (Biometric Passport Standards).
  Input: Image of a person.

  ${bgInstruction}
  ${clothingInstruction}
  ${beautyInstruction}

  CRITICAL BIOMETRIC RULES (STRICT COMPLIANCE):
  1. **DO NOT ALTER FACIAL GEOMETRY**: The shape of eyes, nose, mouth, chin, ears, and head width MUST remain 100% identical to the original.
  2. **DO NOT REMOVE PERMANENT MARKS**: Moles (nốt ruồi), birthmarks, and scars must be preserved. Only remove temporary acne/redness if requested.
  3. **DO NOT CHANGE SKIN TONE**: Maintain the subject's natural ethnicity and skin color.
  4. **OUTPUT**: High Quality JPEG, photorealistic. No cartoonish effects.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';

// Polyfill definitions for ImageCapture API (experimental)
interface PhotoCapabilities {
  redEyeReduction: 'never' | 'always' | 'controllable';
  imageHeight: { min: number; max: number; step: number };
  imageWidth: { min: number; max: number; step: number };
  fillLightMode: string[];
}

interface PhotoSettings {
  fillLightMode?: string;
  imageHeight?: number;
  imageWidth?: number;
  redEyeReduction?: boolean;
}

declare class ImageCapture {
  constructor(track: MediaStreamTrack);
  takePhoto(photoSettings?: PhotoSettings): Promise<Blob>;
  getPhotoCapabilities(): Promise<PhotoCapabilities>;
  grabFrame(): Promise<ImageBitmap>;
}

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

// Strict State Machine for Biometric Validation
type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null); // Separate canvas for low-res analysis

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);
  const [isCapturing, setIsCapturing] = useState(false); // New state for capture loading

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  // AI Validation State
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang xử lý');
  const [instruction, setInstruction] = useState<string>('');

  // Ref to track if an analysis request is currently in flight
  const isAnalyzingRef = useRef(false);
  // Using ReturnType<typeof setInterval> to handle both NodeJS and Browser environments
  const analysisIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    getDevices();
    startCamera();
    return () => {
      stopCamera();
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  // Start AI Analysis Loop when stream is active
  useEffect(() => {
    if (stream && !countdown && !isCapturing) {
      // Run analysis every 5 seconds (increased from 3.5s) to avoid 429 Resource Exhausted
      analysisIntervalRef.current = setInterval(performAIAnalysis, 5000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
  }, [stream, countdown, selectedSize, isCapturing]); 

  // Helper to calculate exact crop coordinates based on current video and selected size
  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = 2/3; // Default 4x6
    if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
    if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;

    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;

    if (sourceRatio > targetRatio) {
      // Source is wider than target: Crop Width (vertical bars)
      // Usually desktop webcam (16:9). We use full height.
      cropH = sourceH;
      cropW = cropH * targetRatio;
      startX = (sourceW - cropW) / 2;
      startY = 0;
    } else {
      // Source is taller than target: Crop Height (horizontal bars)
      // Usually mobile phone (9:16). We have vertical space to slide.
      cropW = sourceW;
      cropH = cropW / targetRatio;
      startX = 0;

      // SHIFT LOGIC:
      // Instead of centering ((sourceH - cropH) / 2), we shift the crop window DOWN relative to the source video.
      // This forces the captured area to be lower on the sensor, capturing more body/shoulders.
      // 0.5 = Center. 0.7 = 70% down.
      const verticalBias = 0.65; 
      startY = (sourceH - cropH) * verticalBias;
    }

    return {
      x: Math.floor(startX),
      y: Math.floor(startY),
      w: Math.floor(cropW),
      h: Math.floor(cropH)
    };
  };

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;

    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');

      if (video.readyState === 4 && ctx) {
        // Calculate the exact crop that the user sees and will capture
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);

        // Resize for analysis (height 320px is sufficient for face detection)
        // Maintain aspect ratio of the CROP, not the full video
        const analysisH = 320;
        const analysisW = Math.floor(analysisH * (crop.w / crop.h));

        canvas.width = analysisW;
        canvas.height = analysisH;

        // Draw MIRRORED crop to match user experience
        ctx.save();
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        ctx.restore();

        const base64 = canvas.toDataURL('image/jpeg', 0.6); // Low quality is enough for structure check

        // Show "Scanning" state briefly if we were previously idle
        if (validationStatus === 'searching') setValidationStatus('analyzing');

        const result = await analyzeIDPhotoFrame(base64);

        // HANDLE QUOTA EXCEEDED (429) - Stop automatic polling
        if (result.feedback === 'AI_LIMIT') {
            if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
            setValidationStatus('valid'); // Enable capture button
            setFeedbackMessage('AI TẠM NGƯNG');
            setInstruction('Đã hết lượt AI. Chuyển chế độ thủ công.');
            return;
        }

        if (!result.faceDetected) {
           setValidationStatus('searching');
           setFeedbackMessage('Không tìm thấy mặt');
           setInstruction('Di chuyển vào khung hình');
        } else if (result.isCompliant) {
           setValidationStatus('valid');
           setFeedbackMessage('ĐẠT CHUẨN');
           setInstruction(result.instruction || 'Giữ nguyên tư thế!');
        } else {
           setValidationStatus('adjusting');
           setFeedbackMessage(result.feedback || 'Cần điều chỉnh');
           setInstruction(result.instruction || 'Chỉnh lại tư thế');
        }
      }
    } catch (err) {
      console.error("AI check failed", err);
    } finally {
      isAnalyzingRef.current = false;
    }
  };

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 3840 }, // Try 4K first
          height: { ideal: 2160 },
        },
        audio: false
      };
      // Fallback to 1080p if 4K fails is handled by 'ideal' usually, but safe to wrap
      let mediaStream;
      try {
          mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (e) {
          mediaStream = await navigator.mediaDevices.getUserMedia({ 
             video: { 
                 deviceId: deviceId ? { exact: deviceId } : undefined,
                 width: { ideal: 1920 }, 
                 height: { ideal: 1080 } 
             } 
          });
      }

      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = useCallback(async () => {
    setIsCapturing(true);
    if (!videoRef.current || !canvasRef.current) {
        setIsCapturing(false);
        return;
    }

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    // --- HIGH QUALITY CAPTURE STRATEGY ---
    // 1. Try ImageCapture API (Hardware Photo)
    // 2. Fallback to Video Snapshot (Software Crop)

    let sourceImage: HTMLImageElement | HTMLVideoElement = video;
    let sourceW = video.videoWidth;
    let sourceH = video.videoHeight;
    let isHighRes = false;

    if (stream) {
        const track = stream.getVideoTracks()[0];
        // Check if ImageCapture is supported (Modern Browsers)
        if (track && 'ImageCapture' in window) {
            try {
                // @ts-ignore - Experimental API
                const imageCapture = new ImageCapture(track);
                const blob = await imageCapture.takePhoto();
                // We create an HTMLImageElement from the high-res blob
                const highResImg = new Image();
                const blobUrl = URL.createObjectURL(blob);

                await new Promise((resolve) => {
                    highResImg.onload = resolve;
                    highResImg.src = blobUrl;
                });

                sourceImage = highResImg;
                sourceW = highResImg.width;
                sourceH = highResImg.height;
                isHighRes = true;

                console.log(`Captured High-Res: ${sourceW}x${sourceH}`);
            } catch (e) {
                console.warn("ImageCapture API failed, falling back to video snapshot", e);
            }
        }
    }

    if (context && sourceW > 0 && sourceH > 0) {
        // Recalculate crop based on actual source dimensions (which might be 4K now)
        const crop = getCropDimensions(sourceW, sourceH);

        canvas.width = crop.w;
        canvas.height = crop.h;

        // Mirror effect logic:
        // Selfies are usually mirrored. 
        // If we use HighRes Photo, it usually comes unmirrored.
        // We ALWAYS mirror to ensure consistency with what user saw on screen.
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 

        // Draw the cropped area
        context.drawImage(sourceImage, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

        const dataUrl = canvas.toDataURL('image/jpeg', 1.0); // Max Quality JPEG
        onCapture(dataUrl);
    }

    setIsCapturing(false);
  }, [onCapture, selectedSize, stream]);

  useEffect(() => {
    if (countdown === null) return;

    if (countdown > 0) {
      const timer = setTimeout(() => {
        setCountdown(countdown - 1);
      }, 1000);
      return () => clearTimeout(timer);
    } else if (countdown === 0) {
      captureFrame();
      setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleCaptureClick = () => {
    // Allows manual override if AI is stuck, but encourages valid state
    setCountdown(3);
  };

  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;
  const is3x4 = selectedSize === PhotoSize.SIZE_3X4;

  // LOGIC FOR GUIDE LINES
  // 4x6 (6cm height): 4mm is ~6.6%
  // 3x4 (4cm height): 3mm is 7.5%
  // 5x5 (5cm height): 3mm is 6%

  let topMarginPercent = 7;
  let marginText = "CÁCH MÉP 4MM";

  if (is3x4) {
      topMarginPercent = 7.5;
      marginText = "CÁCH MÉP 3MM";
  } else if (isUSVisa) {
      topMarginPercent = 6;
      marginText = "CÁCH MÉP 3MM";
  }

  // Determine UI Colors based on Strict State
  const getStatusColor = () => {
    switch (validationStatus) {
      case 'valid': return 'border-green-500 shadow-[0_0_30px_rgba(34,197,94,0.6)]';
      case 'adjusting': return 'border-yellow-400 shadow-[0_0_20px_rgba(250,204,21,0.4)]';
      case 'analyzing': return 'border-blue-400 shadow-[0_0_20px_rgba(96,165,250,0.4)]';
      case 'searching': 
      default: return 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.6)]';
    }
  };

  const getOverlayColor = () => {
     switch (validationStatus) {
      case 'valid': return '#22c55e'; // Green
      case 'adjusting': return '#facc15'; // Yellow
      case 'analyzing': return '#60a5fa'; // Blue
      default: return '#ef4444'; // Red
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative select-none">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md pointer-events-auto"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, idx) => (
            <option key={device.deviceId || idx} value={device.deviceId}>
              {device.label || `Camera ${idx + 1}`}
            </option>
          ))}
        </select>

        {/* Realtime Feedback Status - LARGE & CENTRAL */}
        <div className={`
          absolute top-16 left-1/2 transform -translate-x-1/2
          px-6 py-3 rounded-xl backdrop-blur-md border-2 flex flex-col items-center gap-1 transition-all duration-300 min-w-[280px] text-center shadow-lg
          ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400 text-white scale-110' : 
            validationStatus === 'adjusting' ? 'bg-yellow-600/80 border-yellow-400 text-white' :
            validationStatus === 'analyzing' ? 'bg-blue-600/80 border-blue-400 text-white' :
            'bg-red-600/80 border-red-500 text-white'}
        `}>
          <div className="flex items-center gap-2">
             {validationStatus === 'valid' ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
             ) : (
                <div className="animate-spin w-4 h-4 border-2 border-current border-t-transparent rounded-full" />
             )}
             <span className="font-bold text-sm tracking-wide uppercase">{feedbackMessage}</span>
          </div>
          <span className="text-xs font-medium opacity-90">{instruction}</span>
        </div>
      </div>

      {error && <div className="absolute z-50 bg-red-600 text-white p-4 rounded-lg shadow-xl font-bold animate-pulse">{error}</div>}

      {/* Camera Feed with Aspect Ratio Crop Preview */}
      <div 
        className={`relative transition-all duration-300 bg-black rounded-lg overflow-hidden flex items-center justify-center border-4
          ${isUSVisa ? 'aspect-square h-[75vh]' : is3x4 ? 'aspect-[3/4] h-[75vh]' : 'aspect-[2/3] h-[75vh]'}
          ${getStatusColor()}
        `}
      >
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" 
        />

        {/* =============================================
            ENHANCED SVG OVERLAY WITH MASKING
           ============================================= */}
        <div className="relative z-10 w-full h-full">
          {/* Scanning Effect */}
          {(validationStatus === 'searching' || validationStatus === 'analyzing') && (
            <div className="absolute top-0 left-0 w-full h-1 bg-white/80 shadow-[0_0_15px_rgba(255,255,255,1)] animate-[scan_1.5s_ease-in-out_infinite]" />
          )}

          {/* DYNAMIC GUIDES BASED ON PHOTO SIZE */}
          <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none transition-colors duration-300">
             <defs>
               <mask id="faceMask">
                 <rect x="0" y="0" width="100" height="100" fill="white" />
                 {/* Hole for Face - Adjusted vertically to match margin */}
                 <ellipse cx="50" cy={topMarginPercent + 35} rx={isUSVisa ? 35 : 32} ry={isUSVisa ? 42 : 38} fill="black" />
               </mask>
             </defs>

             {/* Darkened Background */}
             <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#faceMask)" />

             {/* Center Line */}
             <line x1="50" y1="0" x2="50" y2="100" stroke={getOverlayColor()} strokeWidth="0.2" strokeDasharray="2,2" />

             {/* Dynamic Top Margin Indicator */}
             <line x1="0" y1={topMarginPercent} x2="100" y2={topMarginPercent} stroke="#fbbf24" strokeWidth="0.5" strokeDasharray="5,2" />
             <text x="50" y={topMarginPercent - 1} fill="#fbbf24" fontSize="2.5" fontWeight="bold" textAnchor="middle" style={{textShadow: '0 1px 2px black'}}>{marginText}</text>

             {/* Eye Line Guide (Approximate) */}
             <line x1="15" y1={topMarginPercent + 28} x2="85" y2={topMarginPercent + 28} stroke={getOverlayColor()} strokeWidth="0.5" strokeDasharray="4,4" />

             {/* OVAL GUIDE */}
             <ellipse 
                cx="50" 
                cy={topMarginPercent + 35} 
                rx={isUSVisa ? 35 : 32} 
                ry={isUSVisa ? 42 : 38} 
                fill="none" 
                stroke={getOverlayColor()} 
                strokeWidth={validationStatus === 'valid' ? "1" : "0.5"} 
                strokeDasharray={validationStatus === 'valid' ? "0" : "2,2"} 
             />

             <text x="50" y="95" fill="white" fontSize="3" textAnchor="middle" fontWeight="bold" style={{textShadow: '0 1px 2px black'}}>
               {is3x4 ? 'THẺ 3x4' : isUSVisa ? 'VISA 5x5 ' : 'HỘ CHIẾU 4x6'}
             </text>
          </svg>
        </div>

        {/* Countdown Overlay */}
        {(countdown !== null || isCapturing) && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 z-40 backdrop-blur-sm">
             {isCapturing ? (
                <>
                  <div className="w-16 h-16 border-4 border-white border-t-transparent rounded-full animate-spin mb-4"></div>
                  <span className="text-white font-bold tracking-wider">ĐANG CHỤP RAW...</span>
                  <span className="text-white/60 text-xs mt-2">Đang lấy dữ liệu</span>
                </>
             ) : (
                <span className="text-[120px] font-bold text-white animate-ping">{countdown}</span>
             )}
          </div>
        )}
      </div>

      {/* Capture Controls - STRICTLY DISABLED WHEN NOT VALID */}
      <div className="absolute bottom-8 left-0 right-0 flex flex-col justify-end items-center gap-4 z-50 pointer-events-auto">
        <div className={`text-sm font-bold px-4 py-1.5 rounded-full shadow-lg backdrop-blur transition-colors ${validationStatus === 'valid' ? 'bg-green-500 text-white' : 'bg-gray-800/80 text-gray-400'}`}>
           {validationStatus === 'valid' ? '✔CHẤP NHẬN' : '⚠️ Đang xử lý'}
        </div>

        <button
          onClick={handleCaptureClick}
          disabled={countdown !== null || isCapturing}
          className={`
            w-20 h-20 rounded-full border-4 transition-all duration-300 flex items-center justify-center shadow-2xl relative
            ${validationStatus === 'valid' 
              ? 'bg-white border-green-500 hover:border-green-400 hover:scale-105 active:scale-95 cursor-pointer ring-4 ring-green-500/30' 
              : 'bg-gray-700 border-gray-600 opacity-90 cursor-pointer'} 
          `}
        >
           {/* Inner Circle / Lock Icon */}
           <div className={`w-16 h-16 rounded-full transition-all duration-300 flex items-center justify-center ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-600'}`}>
              {validationStatus !== 'valid' && (
                 <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
              )}
           </div>
        </button>
      </div>

      <canvas ref={canvasRef} className="hidden" />
      <canvas ref={analysisCanvasRef} className="hidden" />

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
