export const savePhotoToCloud = async (photo: SavedPhoto): Promise<string | null> => {
  const url = getScriptUrl();
  if (!url) {
    alert("Vui lòng cấu hình 'Google Apps Script URL' trong trang Admin để sử dụng tính năng lưu trữ.");
    return null;
  }

  try {
    // Chuẩn bị payload
    const payload = {
        action: 'save',
        dataUrl: photo.dataUrl,
        timestamp: photo.timestamp,
        settings: photo.settings
    };

    // Gọi đến Google Script Web App
    // Sử dụng 'Content-Type': 'text/plain' để tránh preflight CORS request (OPTIONS)
    // Google Apps Script xử lý tốt text/plain trong doPost
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify(payload),
      headers: {
          'Content-Type': 'text/plain;charset=utf-8', 
      }
    });

    if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (result.success && result.id) {
        return result.id;
    } else {
        const errorMsg = JSON.stringify(result);
        console.error("Lỗi từ Google Script:", errorMsg);

