import React, { useEffect, useState } from 'react';
import { getPhotoById } from '../services/databaseService';
import { SavedPhoto, PhotoSize, AppConfig } from '../types';

interface PhotoViewerProps {
  photoId: string;
  config?: AppConfig; // Optional config for branding
}

const PhotoViewer: React.FC<PhotoViewerProps> = ({ photoId, config }) => {
  const [photo, setPhoto] = useState<SavedPhoto | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Sheet Generation State
  const [isGenerating, setIsGenerating] = useState(false);

  useEffect(() => {
    const fetchPhoto = async () => {
      setLoading(true);
      const data = await getPhotoById(photoId);
      if (data) {
        setPhoto(data);
      } else {
        setError('Không tìm thấy ảnh hoặc ảnh đã bị xóa.');
      }
      setLoading(false);
    };
    fetchPhoto();
  }, [photoId]);

  // --- DOWNLOAD HANDLERS ---
  const downloadImage = (dataUrl: string, filename: string) => {
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadSingle = () => {
    if (!photo) return;
    downloadImage(photo.dataUrl, `Photo-${photo.id}-Single.jpg`);
  };

  const handleDownloadSheet = async () => {
    if (!photo) return;
    setIsGenerating(true);

    try {
        // 130mm x 180mm @ 300 DPI
        // 1 inch = 25.4mm
        const DPI = 300;
        const MM_TO_PX = DPI / 25.4;
        const SHEET_W = 130 * MM_TO_PX;
        const SHEET_H = 180 * MM_TO_PX;

        const canvas = document.createElement('canvas');
        canvas.width = Math.ceil(SHEET_W);
        canvas.height = Math.ceil(SHEET_H);
        const ctx = canvas.getContext('2d');

        if (!ctx) throw new Error("Canvas init failed");

        // 1. Fill White Background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Load Source Image
        const img = new Image();
        img.crossOrigin = "anonymous";
        await new Promise<void>((resolve, reject) => {
            img.onload = () => resolve();
            img.onerror = () => reject(new Error("Image load failed"));
            img.src = photo.dataUrl;
        });

        // 3. Determine Layout (Same logic as PrintPreview)
        const size = photo.settings.size;
        let cols=2, rows=4, photoW_mm=60, photoH_mm=40, rotated=true, maxOnSheet=8;

        if (size === PhotoSize.SIZE_3X4) {
            cols = 4; rows = 4; photoW_mm = 30; photoH_mm = 40; rotated = false; maxOnSheet = 16;
        } else if (size === PhotoSize.SIZE_5X5) {
            cols = 2; rows = 3; photoW_mm = 50; photoH_mm = 50; rotated = false; maxOnSheet = 6;
        }

        const cellW = photoW_mm * MM_TO_PX;
        const cellH = photoH_mm * MM_TO_PX;

        // Grid Dimensions
        const gridW = cols * cellW;
        // Top Margin 5mm (similar to PrintPreview CSS)
        const startY = 5 * MM_TO_PX; 
        const startX = (canvas.width - gridW) / 2;

        // Fill the sheet fully for download
        const countToDraw = maxOnSheet;

        for (let i = 0; i < countToDraw; i++) {
            const r = Math.floor(i / cols);
            const c = i % cols;
            const x = startX + c * cellW;
            const y = startY + r * cellH;

            ctx.save();

            if (rotated) {
                // For 4x6 landscape on portrait sheet, we rotate 90 deg counter-clockwise
                // Center of the cell
                const cx = x + cellW / 2;
                const cy = y + cellH / 2;
                ctx.translate(cx, cy);
                ctx.rotate(-90 * Math.PI / 180);
                // Draw Image centered at (0,0) after rotation
                // Note: cellW in grid is actually the HEIGHT of the photo, cellH is WIDTH
                // But wait, in PrintPreview 'cellW' was layout width. 
                // For 4x6 rotated: layout slot is 60x40 (WxH) ? No.
                // PrintPreview logic: 
                // 4x6 Default: cols=2, rows=4. photoW=60, photoH=40. Rotated=true.
                // Grid cell is 60mm wide, 40mm high.
                // Image is 40mm x 60mm (Portrait source).
                // So we rotate image -90deg to fit into 60x40 slot.
                ctx.drawImage(img, -cellH/2, -cellW/2, cellH, cellW); 

                // Cut line
                ctx.strokeStyle = '#e5e7eb'; // Light gray
                ctx.lineWidth = 2;
                ctx.setLineDash([15, 15]);
                ctx.strokeRect(-cellH/2, -cellW/2, cellH, cellW);

            } else {
                ctx.drawImage(img, x, y, cellW, cellH);

                // Cut line
                ctx.strokeStyle = '#e5e7eb';
                ctx.lineWidth = 2;
                ctx.setLineDash([15, 15]);
                ctx.strokeRect(x, y, cellW, cellH);
            }
            ctx.restore();
        }

        // 4. Add Branding Footer
        const footerH = 15 * MM_TO_PX;
        const footerY = canvas.height - footerH;

        ctx.fillStyle = '#f8fafc'; // Slate-50
        ctx.fillRect(0, footerY, canvas.width, footerH);

        ctx.fillStyle = '#64748b'; // Slate-500
        ctx.font = `bold ${12 * 3}px sans-serif`; // Scale font roughly
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        const shopName = config?.shopName || "ID Photo Booth Pro";
        const dateStr = new Date(photo.timestamp).toLocaleDateString('vi-VN');
        ctx.fillText(`${shopName} - ${dateStr}`, canvas.width / 2, footerY + footerH/2);

        // 5. Download
        const sheetDataUrl = canvas.toDataURL('image/jpeg', 0.95);
        downloadImage(sheetDataUrl, `Photo-${photo.id}-Sheet-13x18.jpg`);

    } catch (e) {
        console.error("Sheet generation failed", e);
        alert("Không thể tạo file in. Vui lòng thử lại.");
    } finally {
        setIsGenerating(false);
    }
  };

  if (loading) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-4">
        <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-4"></div>
        <p className="text-gray-500 font-medium animate-pulse">Đang tải ảnh từ Cloud...</p>
    </div>
  );

  if (error || !photo) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-6 text-center">
        <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-4 shadow-sm">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        </div>
        <h2 className="text-xl font-bold text-gray-800 mb-2">Không tìm thấy ảnh</h2>
        <p className="text-gray-600 mb-6 max-w-xs mx-auto">{error}</p>
        <a href="/" className="px-6 py-2.5 bg-gray-800 text-white rounded-xl font-bold hover:bg-black transition shadow-lg">Về trang chủ</a>
    </div>
  );

  return (
