import React, { useState, useEffect } from 'react';
import { PhotoSettings, PhotoSize, AppConfig } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
  config: AppConfig;
}

// Production URL for QR Codes - Ensures customers can scan from their phone
const APP_DEPLOYMENT_URL = "https://id-photo-booth-pro-926601180918.us-west1.run.app/";

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved,
  onHome,
  config
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [realPhotoId, setRealPhotoId] = useState<string | null>(null);
  const [qrUrl, setQrUrl] = useState<string>('');

  // Layout Logic
  const getLayoutConfig = () => {
    if (size === PhotoSize.SIZE_3X4) {
      return { cols: 4, rows: 4, photoW_mm: 30, photoH_mm: 40, rotated: false, maxOnSheet: 16 };
    } else if (size === PhotoSize.SIZE_5X5) {
      return { cols: 2, rows: 3, photoW_mm: 50, photoH_mm: 50, rotated: false, maxOnSheet: 6 };
    } else {
      // 4x6 Default - Rotated
      return { cols: 2, rows: 4, photoW_mm: 60, photoH_mm: 40, rotated: true, maxOnSheet: 8 };
    }
  };

  const layout = getLayoutConfig();
  const totalPhotosNeeded = settings.printQuantity;
  const totalSheets = Math.ceil(totalPhotosNeeded / layout.maxOnSheet);

  // Tự động lưu lên Cloud khi vào màn hình này để tạo QR Thật
  useEffect(() => {
    const autoSave = async () => {
      setIsSaving(true);
      const dbId = await savePhotoToCloud({
        id: 'temp', // ID sẽ được DB sinh ra
        dataUrl: processedImage,
        timestamp: Date.now(),
        settings: settings
      });

      if (dbId) {
        setRealPhotoId(dbId);

        // Use PRODUCTION URL if available, otherwise fallback to current origin (for dev)
        // This makes sure the QR code works on customer phones even if the shop tablet is on localhost
        let baseUrl = APP_DEPLOYMENT_URL;
        if (!baseUrl || baseUrl === "YOUR_PRODUCTION_URL_HERE") {
             baseUrl = window.location.href.split('?')[0]; 
        }
        // Remove trailing slash
        baseUrl = baseUrl.replace(/\/$/, "");

        const viewerUrl = `${baseUrl}?photoId=${dbId}`;

        console.log("QR Link:", viewerUrl);
        // Tạo QR trỏ về link này
        setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(viewerUrl)}&color=000000&bgcolor=FFFFFF&margin=0`);
      }
      setIsSaving(false);
    };

    // Chỉ lưu 1 lần
    if (!realPhotoId) {
        autoSave();
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const handlePrint = () => {
    window.print();
  };

  const cellW = layout.photoW_mm + 'mm';
  const cellH = layout.photoH_mm + 'mm';

  return (
    <div className="flex flex-col h-full bg-slate-100 relative">

      {/* Header - Hidden on Print */}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center no-print z-20">
        <h1 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
          <svg className="w-6 h-6 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
          Print Preview 
        </h1>
        <div className="flex gap-3">
          <button onClick={onBack} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg transition">Quay lại</button>
        </div>
      </header>

      <div className="flex-1 overflow-hidden flex justify-center items-start gap-8 p-8 bg-slate-100">

        {/* PRINT CONTAINER */}
        <div className="h-full overflow-auto flex flex-col items-center justify-start scrollbar-hide pb-20">

            {/* Loop through sheets */}
            {Array.from({ length: totalSheets }).map((_, sheetIdx) => {
               const startIdx = sheetIdx * layout.maxOnSheet;
               const endIdx = Math.min(startIdx + layout.maxOnSheet, totalPhotosNeeded);
               const countForSheet = endIdx - startIdx;

               return (
                <div 
                  key={sheetIdx}
                  className="bg-white shadow-2xl relative flex flex-col mb-8 print:mb-0 sheet-container"
                  // Style cứng cho kích thước hiển thị và in
                  style={{ 
                    width: '130mm', 
                    height: '180mm', 
                    boxSizing: 'border-box',
                    pageBreakAfter: 'always',
                    breakAfter: 'page'
                  }}
                >
                    {/* Photo Grid Area (Top 160mm) */}
                    <div 
                      className="w-full flex-1 flex flex-wrap content-start items-start justify-center"
                      style={{ paddingTop: '5mm', paddingBottom: '0' }}
                    >
                      {Array.from({ length: countForSheet }).map((_, i) => (
                        <div 
                          key={i} 
                          className="overflow-hidden border border-dashed border-slate-300 relative print:border-slate-400" 
                          style={{ 
                            width: cellW, 
                            height: cellH,
                            display: layout.rotated ? 'flex' : 'block',
                            alignItems: 'center',
                            justifyContent: 'center'
                          }}
                        >
                          <img 
                            src={processedImage} 
                            className="object-cover" 
                            style={{
                               width: layout.rotated ? 'auto' : '100%',
                               height: layout.rotated ? '100%' : '100%',
                               transform: layout.rotated ? 'rotate(-90deg)' : 'none',
                               aspectRatio: layout.rotated ? '2/3' : 'auto' 
                            }}
                            alt="ID Photo" 
                          />
                        </div>
                      ))}
                    </div>

                    {/* Footer Area (Bottom 20mm) */}
                    <div className="h-[20mm] bg-slate-50 border-t border-slate-200 flex items-center justify-between px-6 print:border-t print:border-black">
                        <div className="flex items-center gap-4">
                           {config.logoUrl ? (
                              <img src={config.logoUrl} className="h-10 w-auto object-contain max-w-[120px]" alt="Logo" />
                           ) : (
                              <h3 className="font-bold text-slate-800 text-lg leading-tight">{config.shopName}</h3>
                           )}
                           <div>
                              <p className="text-xs text-slate-500 font-mono mt-0.5">
                                {config.printFooterText} | Sheet {sheetIdx + 1}/{totalSheets}
                              </p>
                           </div>
                        </div>
                        {/* QR Code Real Link */}
                        <div className="bg-white p-1 rounded border border-slate-200">
                            {qrUrl ? (
                                <img src={qrUrl} className="w-[14mm] h-[14mm] mix-blend-multiply opacity-90" alt="QR" />
                            ) : (
                                <div className="w-[14mm] h-[14mm] bg-gray-200 animate-pulse"></div>
                            )}
                        </div>
                    </div>
                </div>
               );
            })}
        </div>

        {/* Action Panel - Right Sidebar (No Print) */}
        <div className="w-80 bg-white p-6 rounded-2xl shadow-xl flex flex-col gap-6 no-print h-fit sticky top-6">

          <div>
            <div className="flex justify-between items-center mb-4">
               <h3 className="font-bold text-gray-800">Thao tác chính</h3>
               <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded-full font-bold">{settings.printQuantity} ảnh</span>
            </div>

            <button 
              onClick={handlePrint}
              disabled={isSaving}
              className="group w-full py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition-all flex flex-col items-center justify-center gap-1 mb-3 disabled:bg-gray-400"
            >
              <div className="flex items-center gap-2">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                <span>{isSaving ? 'ĐANG TẠO DỮ LIỆU...' : 'IN NGAY'}</span>
              </div>
              <span className="text-[10px] opacity-80 font-normal">Khổ 13x18cm (Ctrl + P)</span>
            </button>

            <div className="bg-yellow-50 p-3 rounded-lg border border-yellow-200 text-xs text-yellow-800 mb-4">
                <strong>Lưu ý in:</strong> Hãy chọn khổ giấy "13x18cm" hoặc "5x7in" trong cài đặt máy in. Tắt "Header and Footer".
            </div>

            <div className="bg-slate-50 border border-slate-200 rounded-xl p-3 text-center">
               <h3 className="font-bold text-gray-800 mb-2 text-xs uppercase tracking-wider">Mã QR Tải Ảnh</h3>
               {qrUrl ? (
                   <div className="flex flex-col items-center">
                       <img src={qrUrl} alt="QR Big" className="w-32 h-32 mix-blend-multiply mb-2" />
                       <p className="text-[10px] text-gray-500">Quét để tải ảnh gốc</p>
                       <p className="text-[9px] font-mono text-gray-400 mt-1">ID: {realPhotoId}</p>
                   </div>
               ) : (
                   <div className="h-32 flex items-center justify-center text-xs text-gray-400">Đang tạo mã QR...</div>
               )}
            </div>
          </div>

           <button onClick={onHome} className="w-full p-2 text-xs font-bold text-gray-400 hover:text-gray-600 transition">
              Về trang chủ
           </button>
        </div>

      </div>

      <style>{`
        @media print {
            @page {
                size: 130mm 180mm;
                margin: 0;
            }
            body {
                background: white;
                margin: 0;
                padding: 0;
            }
            /* Ẩn tất cả mọi thứ */
            body * {
                visibility: hidden;
            }
            /* Chỉ hiện container khổ giấy */
            .sheet-container, .sheet-container * {
                visibility: visible;
            }
            .sheet-container {
                position: absolute;
                left: 0;
                top: 0;
                margin: 0;
                padding: 0;
                border: none !important;
                box-shadow: none !important;
            }
            .no-print {
                display: none !important;
            }
        }
      `}</style>
    </div>
  );
};

