    e.preventDefault();
    // Use the password from config or fallback to 'admin'
    const targetPass = config.adminPassword || 'admin';

    if (adminPass === targetPass) {
      setIsAdminMode(true);
      setShowAdminLogin(false);
      setAdminPass('');
    } else {
      alert('Sai mật khẩu!');
