import { SavedPhoto } from "../types";
import { getConfig } from "./configService";

// --- CẤU HÌNH GOOGLE APPS SCRIPT ---
// URL sẽ được lấy từ Config Service do người dùng nhập trong Admin Panel
const getScriptUrl = () => {
    const config = getConfig();
    return config.googleScriptUrl || '';
};

/**
 * Lưu ảnh lên Google Drive & Sheets thông qua Google Apps Script Web App.
 */
export const savePhotoToCloud = async (photo: SavedPhoto): Promise<string | null> => {
  const url = getScriptUrl();
  if (!url) {
    alert("Vui lòng cấu hình 'Google Apps Script URL' trong trang Admin để sử dụng tính năng lưu trữ.");
    return null;
  }

  try {
    // Chuẩn bị payload
    const payload = {
        action: 'save',
        dataUrl: photo.dataUrl,
        timestamp: photo.timestamp,
        settings: photo.settings
    };

    // Gọi đến Google Script Web App
    // Sử dụng 'Content-Type': 'text/plain' để tránh preflight CORS request (OPTIONS)
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify(payload),
      headers: {
          'Content-Type': 'text/plain;charset=utf-8', 
      }
    });

    if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (result.success && result.id) {
        return result.id;
    } else {
        const errorMsg = JSON.stringify(result);
        console.error("Lỗi từ Google Script:", errorMsg);

        if (errorMsg.includes("getSheetByName")) {
             alert("LỖI CẤU HÌNH SERVER:\nScript của bạn đang gặp lỗi: 'Cannot read properties of null (reading getSheetByName)'.\n\nNGUYÊN NHÂN:\nBạn đã tạo Script độc lập (Standalone) nên nó không tìm thấy Google Sheet.\n\nCÁCH SỬA:\n1. Mở một Google Sheet mới.\n2. Chọn menu 'Tiện ích mở rộng' (Extensions) > 'Apps Script'.\n3. Dán code vào đó và Deploy lại.\n4. Lấy URL mới dán vào Admin.");
        } else {
             alert(`Lỗi lưu trữ: ${result.error || 'Không xác định'}`);
        }
        return null;
    }

  } catch (error: any) {
    console.error("Lỗi lưu trữ (Fetch):", error);

    // Xử lý lỗi Failed to fetch (thường do CORS hoặc URL sai hoặc Quyền truy cập chưa mở)
    const msg = error.message || '';
    if (msg.includes('Failed to fetch') || msg.includes('NetworkError')) {
        alert("LỖI KẾT NỐI SERVER (Failed to fetch):\n\nNguyên nhân phổ biến:\n1. URL Script sai hoặc chưa Deploy bản mới (New Deployment).\n2. Quyền truy cập (Who has access) chưa chọn là 'Anyone' (Bất kỳ ai).\n\nCách sửa:\n- Vào Script > Deploy > New Deployment.\n- Chọn 'Web app'.\n- Execute as: 'Me'.\n- Who has access: 'Anyone' (QUAN TRỌNG).\n- Copy URL mới dán vào Admin.");
    } else {
        alert("Không thể kết nối đến Google Script. Vui lòng kiểm tra console.");
    }
    return null;
  }
};

/**
 * Lấy ảnh từ Google Drive/Sheet bằng ID
 */
export const getPhotoById = async (id: string): Promise<SavedPhoto | null> => {
  const url = getScriptUrl();
  if (!url) return null;

  try {
    const fetchUrl = `${url}?action=get&id=${id}`;

    const response = await fetch(fetchUrl);

    if (!response.ok) {
         throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (result && result.id) {
        return result as SavedPhoto;
    }

    return null;

  } catch (error) {
    console.error("Lỗi lấy ảnh:", error);
    return null;
  }
};

/**
 * Lấy danh sách ảnh từ Cloud (Google Sheets)
 * Action: 'list'
 */
export const getPhotosFromCloud = async (): Promise<SavedPhoto[]> => {
  const url = getScriptUrl();
  if (!url) return [];

  try {
    const fetchUrl = `${url}?action=list`;
    const response = await fetch(fetchUrl);

    if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    // Google Script nên trả về { success: true, photos: [...] }
    if (result.success && Array.isArray(result.photos)) {
        // Sắp xếp mới nhất lên đầu
        return result.photos.sort((a: SavedPhoto, b: SavedPhoto) => b.timestamp - a.timestamp);
    }

    return [];

  } catch (error) {
    console.error("Lỗi lấy danh sách ảnh:", error);
    return []; 
  }
};

/**
 * Xóa ảnh khỏi Cloud
 * Action: 'delete'
 */
export const deletePhotoFromCloud = async (id: string): Promise<boolean> => {
  const url = getScriptUrl();
  if (!url) return false;

  try {
    const payload = { action: 'delete', id };

    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify(payload),
      headers: {
          'Content-Type': 'text/plain;charset=utf-8', 
      }
    });

    if (!response.ok) return false;

    const result = await response.json();
    return result.success === true;

  } catch (error) {
    console.error("Lỗi xóa ảnh:", error);
    return false;
  }
};

