import { SavedPhoto, AppConfig } from "../types";
import { getConfig, saveConfig } from "./configService";

// --- CẤU HÌNH GOOGLE APPS SCRIPT ---
// URL sẽ được lấy từ Config Service do người dùng nhập trong Admin Panel
const getScriptUrl = () => {
    const config = getConfig();
    return config.googleScriptUrl || '';
};

/**
 * Lưu ảnh lên Google Drive & Sheets thông qua Google Apps Script Web App.
 */
export const savePhotoToCloud = async (photo: SavedPhoto): Promise<string | null> => {
  const url = getScriptUrl();
  if (!url) {
    // Không alert ở đây để tránh spam khi auto-save, chỉ log
    console.warn("Chưa cấu hình Google Script URL.");
    return null;
  }

  try {
    // Chuẩn bị payload
    const payload = {
        action: 'save',
        dataUrl: photo.dataUrl,
        timestamp: photo.timestamp,
        settings: photo.settings
    };

    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify(payload),
      headers: { 'Content-Type': 'text/plain;charset=utf-8' }
    });

    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const result = await response.json();

    if (result.success && result.id) {
        return result.id;
    } else {
        console.error("Lỗi từ Google Script:", result);
        return null;
    }
  } catch (error: any) {
    console.error("Lỗi lưu trữ (Fetch):", error);
    return null;
  }
};

/**
 * Lấy danh sách ảnh từ Cloud (Google Sheets)
 */
export const getPhotosFromCloud = async (): Promise<SavedPhoto[]> => {
  const url = getScriptUrl();
  if (!url) return [];

  try {
    const fetchUrl = `${url}?action=list`;
    const response = await fetch(fetchUrl);

    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

    const result = await response.json();

    if (result.success && Array.isArray(result.photos)) {
        return result.photos.sort((a: SavedPhoto, b: SavedPhoto) => b.timestamp - a.timestamp);
    }
    return [];
  } catch (error) {
    console.error("Lỗi lấy danh sách ảnh:", error);
    return []; 
  }
};

/**
 * Lấy ảnh chi tiết bằng ID
 */
export const getPhotoById = async (id: string): Promise<SavedPhoto | null> => {
  const url = getScriptUrl();
  if (!url) return null;

  try {
    const fetchUrl = `${url}?action=get&id=${id}`;
    const response = await fetch(fetchUrl);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const result = await response.json();
    return (result && result.id) ? result as SavedPhoto : null;
  } catch (error) {
    console.error("Lỗi lấy ảnh:", error);
    return null;
  }
};

/**
 * Xóa ảnh khỏi Cloud
 */
export const deletePhotoFromCloud = async (id: string): Promise<boolean> => {
  const url = getScriptUrl();
  if (!url) return false;

  try {
    const payload = { action: 'delete', id };
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify(payload),
      headers: { 'Content-Type': 'text/plain;charset=utf-8' }
    });
    if (!response.ok) return false;
    const result = await response.json();
    return result.success === true;
  } catch (error) {
    console.error("Lỗi xóa ảnh:", error);
    return false;
  }
};

/**
 * LƯU CẤU HÌNH APP LÊN CLOUD (Sync Settings)
 */
export const saveAppConfigToCloud = async (config: AppConfig): Promise<boolean> => {
    // QUAN TRỌNG: Sử dụng URL trực tiếp từ config truyền vào (nếu có)
    // để đảm bảo lấy đúng URL mới nhất vừa nhập, thay vì lấy từ localStorage cũ.
    const url = config.googleScriptUrl || getScriptUrl();
    if (!url) return false;

    try {
        const payload = {
            action: 'saveConfig',
            config: config
        };
        const response = await fetch(url, {
            method: 'POST',
            body: JSON.stringify(payload),
            headers: { 'Content-Type': 'text/plain;charset=utf-8' }
        });
        const result = await response.json();
        return result.success === true;
    } catch (e) {
        console.error("Lỗi lưu cấu hình:", e);
        return false;
    }
};

/**
 * TẢI CẤU HÌNH APP TỪ CLOUD (Sync Settings)
 */
export const getAppConfigFromCloud = async (): Promise<AppConfig | null> => {
    const url = getScriptUrl();
    if (!url) return null;

    try {
        const fetchUrl = `${url}?action=getConfig`;
        const response = await fetch(fetchUrl);
        const result = await response.json();

        if (result.success && result.config) {
            // Lưu vào localStorage ngay
            saveConfig(result.config);
            return result.config;
        }
        return null;
    } catch (e) {
        console.error("Lỗi tải cấu hình:", e);
        return null;
    }
};

