       const rows = sheet.getDataRange().getValues();
       for (let i = 0; i < rows.length; i++) {
         if (rows[i][0] == data.id) {
           sheet.deleteRow(i + 1);
           return ContentService.createTextOutput(JSON.stringify({ success: true }));
         }
       }
       return ContentService.createTextOutput(JSON.stringify({ success: false, error: 'Not found' }));
    }

    // --- ACTION 3: LƯU ẢNH MỚI (SAVE PHOTO) ---
    if (data.action === 'save') {
      const sheet = getOrCreateSheet(ss, 'Photos');
      const id = 'ID_' + new Date().getTime(); // Tạo ID mới
      // Cấu trúc cột: ID | Ảnh Base64 | Thời gian | Cài đặt JSON
      sheet.appendRow([id, data.dataUrl, data.timestamp, JSON.stringify(data.settings)]);
      return ContentService.createTextOutput(JSON.stringify({ success: true, id: id }));
    }

    return ContentService.createTextOutput(JSON.stringify({ success: false, error: 'Unknown action' }));
  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ success: false, error: e.toString() }));
  } finally {
    lock.releaseLock();
  }
}

function doGet(e) {
  const action = e.parameter.action;
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // --- ACTION: LẤY CẤU HÌNH (GET CONFIG) ---
  if (action === 'getConfig') {
     const configSheet = getOrCreateSheet(ss, 'AppConfig');
     const json = configSheet.getRange(1, 1).getValue();
     let config = null;
     if (json) {
        try { config = JSON.parse(json); } catch(e) {}
     }
     return ContentService.createTextOutput(JSON.stringify({ success: true, config: config }));
  }

  // --- ACTION: LẤY CHI TIẾT 1 ẢNH ---
  if (action === 'get') {
    const sheet = getOrCreateSheet(ss, 'Photos');
    const rows = sheet.getDataRange().getValues();
    const id = e.parameter.id;

    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] == id) {
        const photo = {
          id: rows[i][0],
          dataUrl: rows[i][1],
          timestamp: rows[i][2],
          settings: JSON.parse(rows[i][3])
        };
        return ContentService.createTextOutput(JSON.stringify(photo));
      }
    }
    return ContentService.createTextOutput(JSON.stringify({ error: 'Not found' }));
  }

  // --- ACTION: LẤY DANH SÁCH ẢNH (LIST) ---
  if (action === 'list') {
    const sheet = getOrCreateSheet(ss, 'Photos');
    const rows = sheet.getDataRange().getValues();
    const photos = [];

    // Giới hạn lấy 50 ảnh gần nhất để tránh nặng
    const start = Math.max(0, rows.length - 50);

    for (let i = start; i < rows.length; i++) {
      if (rows[i][0]) { // Kiểm tra có ID
        try {
          photos.push({
             id: rows[i][0],
             dataUrl: rows[i][1], // Ảnh Base64 (có thể nặng)
             timestamp: rows[i][2],
             settings: JSON.parse(rows[i][3])
          });
        } catch (e) {}
      }
    }
    return ContentService.createTextOutput(JSON.stringify({ success: true, photos: photos }));
  }

  return ContentService.createTextOutput(JSON.stringify({ error: 'Invalid action' }));
}

function getOrCreateSheet(ss, name) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
  }
  return sheet;
}
