                     </button>
                 </div>
                 <div className="flex-1 overflow-auto p-6 bg-slate-50 font-mono text-xs">
                     <div className="bg-yellow-50 text-yellow-800 p-4 rounded-xl border border-yellow-200 mb-4 font-sans text-sm">
