              <h3 className="text-xl font-bold mb-6 text-gray-800">{editingItem ? 'Sửa trang phục' : 'Thêm trang phục mới'}</h3>
              <div className="space-y-5">
                 <InputGroup label="Tên hiển thị (Label)" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z"></path></svg>}>
                    <input type="text" className={iconInputClass} value={tempClothing.label} onChange={e => setTempClothing({...tempClothing, label: e.target.value})} placeholder="Ví dụ: Vest Đen" />
