                        <option value="female">Nữ</option>
                      </select>
                    </InputGroup>
                    <InputGroup label="Biểu tượng" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>}>
                      <input type="text" className={`${iconInputClass} text-center`} value={tempClothing.icon} onChange={e => setTempClothing({...tempClothing, icon: e.target.value})} placeholder="👔" />
                    </InputGroup>
                 </div>
                 <InputGroup label="Câu lệnh AI (Prompt)" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>}>
                    <textarea className={`${iconInputClass} h-24 text-sm`} value={tempClothing.prompt} onChange={e => setTempClothing({...tempClothing, prompt: e.target.value})} placeholder="wearing a black suit..." />
                 </InputGroup>
                 <InputGroup label="Màu viền (Tailwind CSS)" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01"></path></svg>}>
                    <input type="text" className={`${iconInputClass} font-mono text-xs`} value={tempClothing.color} onChange={e => setTempClothing({...tempClothing, color: e.target.value})} placeholder="border-blue-500" />
                 </InputGroup>
              </div>
              <div className="flex justify-end gap-3 mt-8 pt-4 border-t border-gray-100">
                 <button onClick={() => setShowClothingModal(false)} className="px-5 py-2.5 text-gray-500 font-bold hover:bg-gray-100 rounded-xl transition">Hủy</button>
                 <button onClick={saveClothingItem} className="px-6 py-2.5 bg-brand-600 text-white font-bold rounded-xl hover:bg-brand-700 shadow-lg shadow-brand-500/20 transition">Lưu lại</button>
              </div>
           </div>
        </div>
      )}

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        .scrollbar-hide::-webkit-scrollbar {
            display: none;
        }
        .scrollbar-hide {
            -ms-overflow-style: none;
            scrollbar-width: none;
        }
      `}</style>
    </div>
  );
};

export default AdminDashboard;

export enum PhotoSize {
  SIZE_3X4 = '3x4',
  SIZE_4X6 = '4x6',
  SIZE_5X5 = '5x5' // US Visa / International
}

export enum BackgroundType {
  WHITE = 'white',
  BLUE = 'blue',
  GRAY = 'gray', // Added neutral gray
  ORIGINAL = 'original'
}

export enum AppStep {
  CONFIG = 'config', // New start screen
  CAPTURE = 'capture',
  EDIT = 'edit',
  PRINT = 'print'
}

export enum SkinToneType {
  NATURAL = 'natural', // Tự nhiên
  FAIR = 'fair',       // Trắng sáng
  ROSY = 'rosy',       // Trắng hồng
  TAN = 'tan'          // Ngăm khỏe
}

export interface BeautySettings {
  // Skin
  smoothSkin: number;        // 0-100 (AI Strength)
  removeBlemishes: boolean;  // AI Toggle

  // Skin Tone (Client-side)
  skinToneType: SkinToneType;
  skinToneIntensity: number; // 0-100

  // Lighting & Contrast (Client-side)
  lighting: number;          // -50 to +50
  contrast: number;          // -50 to +50

  // Detailed Makeup (AI)
  lipstickColor: 'red' | 'pink' | 'orange' | 'natural';
  lipstickIntensity: number; // 0-100

  blushIntensity: number;    // 0-100

  // New Features
  eyebrowIntensity: number;  // 0-100 (Kẻ chân mày)
  contourIntensity: number;  // 0-100 (Tạo khối)
