    applyTheme(form.themeColorHex);
  }, [form.themeColorHex]);

  const handleChange = (field: keyof AppConfig, value: any) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  // --- SAVE & AUTO SYNC ---
  const handleSave = async () => {
    setIsSyncing(true);
    setSaveStatus('Đang lưu...');

    // 1. Save Local First
    saveConfig(form);
    onUpdateConfig(form);

    // 2. Auto Sync to Cloud if URL exists
    let syncMsg = '';
    if (form.googleScriptUrl) {
       try {
           const success = await saveAppConfigToCloud(form);
           if (success) {
               syncMsg = ' & Đã đồng bộ Cloud';
           } else {
               syncMsg = ' (Lỗi đồng bộ Cloud - Kiểm tra Script)';
           }
       } catch (e) {
           console.error("Auto-sync error:", e);
           // Swallow error to prevent crashing, just notify user
           syncMsg = ' (Lỗi kết nối Cloud)';
       }
    }

    setIsSyncing(false);
    setSaveStatus(`Đã lưu máy này${syncMsg}!`);
    setTimeout(() => setSaveStatus(''), 4000);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) { // Limit 1MB
        alert("Ảnh quá lớn! Vui lòng chọn ảnh dưới 1MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, logoUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveLogo = () => {
    setForm(prev => ({ ...prev, logoUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

