export const getConfig = (): AppConfig => {
  const saved = localStorage.getItem(CONFIG_KEY);
  if (!saved) return DEFAULT_CONFIG;
  try {
    const parsed = JSON.parse(saved);

    // Only retrieve the URL from local storage.
    // Everything else resets to Default until fetched from Cloud.
    // If local storage URL is empty, use the Default (which is now the valid provided URL).
    let cleanUrl = parsed.googleScriptUrl;

    if (!cleanUrl) {
        cleanUrl = DEFAULT_CONFIG.googleScriptUrl;
    }

    return { 
      ...DEFAULT_CONFIG, 
      googleScriptUrl: cleanUrl // Only field we trust from Local Storage
    };
  } catch (e) {
    return DEFAULT_CONFIG;
  }
};

// Helper to convert Hex to RGB numbers string (e.g. "59 130 246") for Tailwind vars
const hexToRgb = (hex: string) => {
  let r = 0, g = 0, b = 0;
  // 3 digits
  if (hex.length === 4) {
    r = parseInt("0x" + hex[1] + hex[1]);
    g = parseInt("0x" + hex[2] + hex[2]);
    b = parseInt("0x" + hex[3] + hex[3]);
  } else if (hex.length === 7) {
    r = parseInt("0x" + hex[1] + hex[2]);
    g = parseInt("0x" + hex[3] + hex[4]);
    b = parseInt("0x" + hex[5] + hex[6]);
  }
  return `${r} ${g} ${b}`;
};

// Apply CSS variables to root
export const applyTheme = (hexColor: string) => {
  if (!hexColor) return;
  const rgb = hexToRgb(hexColor);
  const root = document.documentElement;

  root.style.setProperty('--brand-500', rgb);
  root.style.setProperty('--brand-600', rgb);
  root.style.setProperty('--brand-700', rgb);

  root.style.setProperty('--brand-50', rgb);
  root.style.setProperty('--brand-100', rgb);
  root.style.setProperty('--brand-200', rgb);
};

// Update Browser Tab Icon
export const updateFavicon = (logoUrl?: string) => {
  const link = document.getElementById('dynamic-favicon') as HTMLLinkElement;
  if (link) {
    // If logoUrl is present, use it. Otherwise use a default encoded SVG camera icon
    if (logoUrl) {
      link.href = logoUrl;
