import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, ClothingItem, LipstickOption, PhotoSize } from '../types';
import { saveConfig, applyTheme } from '../services/configService';
import { saveAppConfigToCloud } from '../services/databaseService';

interface AdminDashboardProps {
  currentConfig: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  onExit: () => void;
}

const COLORS = [
  { hex: '#3b82f6', label: 'Xanh Dương' },
  { hex: '#ef4444', label: 'Đỏ' },
  { hex: '#10b981', label: 'Xanh Lá' },
  { hex: '#8b5cf6', label: 'Tím' },
  { hex: '#f59e0b', label: 'Vàng Cam' },
  { hex: '#ec4899', label: 'Hồng' },
  { hex: '#0f172a', label: 'Đen' },
];

// Helper component for styled inputs
const InputGroup = ({ label, icon, children }: { label: string, icon?: React.ReactNode, children?: React.ReactNode }) => (
  <div className="group w-full">
    <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">{label}</label>
    <div className="relative w-full">
      {icon && <div className="absolute left-3 top-3.5 text-slate-400 group-focus-within:text-brand-500 transition-colors pointer-events-none z-10">{icon}</div>}
      {children}
    </div>
  </div>
);

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentConfig, onUpdateConfig, onExit }) => {
  const [form, setForm] = useState<AppConfig>(currentConfig);
  const [activeTab, setActiveTab] = useState<'general' | 'design' | 'clothing' | 'config' | 'security'>('general');
  const [saveStatus, setSaveStatus] = useState('');
  const [isSyncing, setIsSyncing] = useState(false); 
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Clothing Editor State
  const [editingItem, setEditingItem] = useState<ClothingItem | null>(null);
  const [showClothingModal, setShowClothingModal] = useState(false);
  const [tempClothing, setTempClothing] = useState<ClothingItem>({
    id: '', label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-gray-300'
  });

  // Lipstick Editor State
  const [newLipstick, setNewLipstick] = useState<LipstickOption>({ id: '', label: '', hex: '#ff0000' });

  useEffect(() => {
    // Live preview theme change
    applyTheme(form.themeColorHex);
  }, [form.themeColorHex]);

  const handleChange = (field: keyof AppConfig, value: any) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  // --- SAVE & AUTO SYNC (STRICT CLOUD ONLY) ---
  const handleSave = async () => {
    setIsSyncing(true);
    setSaveStatus('Đang đẩy lên Cloud...');

    // Strict Check: URL Required
    if (!form.googleScriptUrl || !form.googleScriptUrl.startsWith('http')) {
        setIsSyncing(false);
        setSaveStatus('Lỗi: URL Cloud không hợp lệ');
        alert("Lỗi cấu hình hệ thống: Thiếu URL kết nối Data Center.");
        return;
    }

    try {
        // 1. Attempt Cloud Save (The Source of Truth)
        const success = await saveAppConfigToCloud(form);

        if (success) {
            // 2. Only if Cloud succeeds, we update the Runtime State
            onUpdateConfig(form);

            // 3. We persist ONLY the URL to local storage (for reconnecting on reload)
            // The service is modified to ignore other fields.
            saveConfig(form);

            setSaveStatus('✔ Đã lưu vào Cloud');
        } else {
            setSaveStatus('❌ Lỗi Cloud: Không thể lưu!');
            alert("Lỗi khi lưu vào Google Sheets. Vui lòng kiểm tra lại kết nối mạng.");
        }
    } catch (e) {
        console.error("Cloud Sync Error", e);
        setSaveStatus('❌ Lỗi kết nối mạng');
        alert("Không thể kết nối Internet. Dữ liệu chưa được lưu.");
    } finally {
        setIsSyncing(false);
        setTimeout(() => setSaveStatus(''), 5000);
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) { // Limit 1MB
        alert("Ảnh quá lớn! Vui lòng chọn ảnh dưới 1MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, logoUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveLogo = () => {
    setForm(prev => ({ ...prev, logoUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // --- CLOTHING CRUD ---
  const openAddClothing = () => {
    setEditingItem(null);
    setTempClothing({ id: `custom_${Date.now()}`, label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-blue-500' });
    setShowClothingModal(true);
  };

  const openEditClothing = (item: ClothingItem) => {
    setEditingItem(item);
    setTempClothing({ ...item });
    setShowClothingModal(true);
  };

  const saveClothingItem = () => {
    let newOptions = [...form.clothingOptions];
    if (editingItem) {
      // Edit
      newOptions = newOptions.map(item => item.id === editingItem.id ? tempClothing : item);
    } else {
      // Add
      newOptions.push(tempClothing);
    }
    setForm(prev => ({ ...prev, clothingOptions: newOptions }));
    setShowClothingModal(false);
  };

  const deleteClothingItem = (id: string) => {
    if (confirm('Bạn có chắc chắn muốn xóa trang phục này?')) {
      const newOptions = form.clothingOptions.filter(item => item.id !== id);
      setForm(prev => ({ ...prev, clothingOptions: newOptions }));
    }
  };

  // --- LIPSTICK CRUD ---
  const addLipstick = () => {
    if (!newLipstick.label) return;
    const id = `lip_${Date.now()}`;
    setForm(prev => ({
        ...prev,
        lipstickOptions: [...prev.lipstickOptions, { ...newLipstick, id }]
    }));
    setNewLipstick({ id: '', label: '', hex: '#ff0000' });
  };

  const deleteLipstick = (id: string) => {
      setForm(prev => ({
          ...prev,
          lipstickOptions: prev.lipstickOptions.filter(l => l.id !== id)
      }));
  };

  // --- RULES EDITOR ---
  const handleRuleChange = (size: string, text: string) => {
      const rulesArray = text.split('\n').filter(line => line.trim() !== '');
