payload.text:
Dưới đây là toàn bộ mã nguồn **Google Apps Script** đã được tối ưu hóa để hoạt động 100% với ứng dụng của bạn. Mã này xử lý việc lưu trữ dữ liệu vào Google Sheets, đảm bảo tốc độ và tránh lỗi khi nhiều người cùng lưu một lúc.

### Hướng dẫn cài đặt (Bắt buộc làm theo):

1.  Truy cập [script.google.com](https://script.google.com/) và mở dự án của bạn (trùng với URL bạn đã cung cấp).
2.  Xóa toàn bộ code cũ trong file `Code.gs`.
3.  **Copy và Paste** toàn bộ đoạn code dưới đây vào.
4.  Bấm nút **Deploy** (Triển khai) -> **New Deployment** (Triển khai mới).
5.  Chọn loại: **Web App**.
6.  Cấu hình:
    *   Description: `Update v1`
    *   Execute as: **Me (Tôi)**.
    *   Who has access: **Anyone (Bất kỳ ai)**.
7.  Bấm **Deploy**. (Nếu URL thay đổi, hãy cập nhật lại vào code React, nhưng thường nếu Update deployment thì URL cũ vẫn chạy tốt nếu bạn chọn Manage Deployments -> Edit -> New Version).

### Code Google Apps Script (Code.gs)

```javascript
/**
 * ID PHOTO BOOTH PRO - BACKEND API
 * Xử lý lưu trữ dữ liệu vào Google Sheets
 */

// Tên các Sheet
const SHEET_CONFIG = 'AppConfig';
const SHEET_PHOTOS = 'Photos';

function doPost(e) {
  const lock = LockService.getScriptLock();
  // Đợi tối đa 30 giây để tránh xung đột dữ liệu khi nhiều máy cùng lưu
  try {
    lock.waitLock(30000); 
  } catch (e) {
    return responseJSON({ success: false, error: 'Server busy, try again.' });
  }

  try {
    // Lấy dữ liệu gửi lên
    const postData = JSON.parse(e.postData.contents);
    const action = postData.action;
    const ss = SpreadsheetApp.getActiveSpreadsheet();

    // --- CASE 1: LƯU CẤU HÌNH (SAVE CONFIG) ---
    if (action === 'saveConfig') {
      const sheet = getOrCreateSheet(ss, SHEET_CONFIG);
      // Xóa dữ liệu cũ và ghi đè cấu hình mới vào ô A1
      sheet.clearContents();
      sheet.getRange(1, 1).setValue(JSON.stringify(postData.config));
      return responseJSON({ success: true });
    }

    // --- CASE 2: LƯU ẢNH (SAVE PHOTO) ---
    if (action === 'save') {
      const sheet = getOrCreateSheet(ss, SHEET_PHOTOS);

      // Tạo header nếu chưa có
      if (sheet.getLastRow() === 0) {
        sheet.appendRow(['ID', 'Timestamp', 'Settings_JSON', 'Image_Base64']);
      }

      // Tạo ID duy nhất dựa trên thời gian
      const id = 'IMG_' + new Date().getTime() + '_' + Math.floor(Math.random() * 1000);
      const timestamp = new Date().toISOString();
      const settingsStr = JSON.stringify(postData.settings);

      // Dữ liệu ảnh Base64 (Cắt bớt header data:image/... nếu cần thiết để tiết kiệm, 
      // nhưng ở đây ta giữ nguyên để frontend dễ hiển thị)
      const imageBase64 = postData.dataUrl;

      // Thêm dòng mới vào cuối bảng
      sheet.appendRow([id, timestamp, settingsStr, imageBase64]);

      return responseJSON({ success: true, id: id });
    }

    // --- CASE 3: XÓA ẢNH (DELETE PHOTO) ---
    if (action === 'delete') {
      const sheet = getOrCreateSheet(ss, SHEET_PHOTOS);
      const data = sheet.getDataRange().getValues();
      const idToDelete = postData.id;

      // Duyệt ngược từ dưới lên để xóa an toàn
      for (let i = data.length - 1; i >= 1; i--) {
        if (data[i][0] == idToDelete) {
          sheet.deleteRow(i + 1);
          return responseJSON({ success: true });
        }
      }
      return responseJSON({ success: false, error: 'Photo ID not found' });
    }

    return responseJSON({ success: false, error: 'Invalid action in doPost' });

  } catch (error) {
    return responseJSON({ success: false, error: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

function doGet(e) {
  try {
    const action = e.parameter.action;
    const ss = SpreadsheetApp.getActiveSpreadsheet();

    // --- CASE 1: LẤY CẤU HÌNH (GET CONFIG) ---
    if (action === 'getConfig') {
      const sheet = getOrCreateSheet(ss, SHEET_CONFIG);
      const data = sheet.getRange(1, 1).getValue();
      let config = null;
      if (data) {
        try { config = JSON.parse(data); } catch(err) {}
      }
      return responseJSON({ success: true, config: config });
    }

    // --- CASE 2: LẤY DANH SÁCH ẢNH (LIST PHOTOS) ---
    if (action === 'list') {
      const sheet = getOrCreateSheet(ss, SHEET_PHOTOS);
      const lastRow = sheet.getLastRow();

      if (lastRow <= 1) {
        return responseJSON({ success: true, photos: [] });
      }

      // Chỉ lấy 30 ảnh mới nhất để tránh lỗi Timeout do dữ liệu quá lớn
      // Cấu trúc cột: 0:ID, 1:Time, 2:Settings, 3:Image
      const limit = 30; 
      const startRow = Math.max(2, lastRow - limit + 1);
      const numRows = lastRow - startRow + 1;

      const data = sheet.getRange(startRow, 1, numRows, 4).getValues();

      // Đảo ngược để ảnh mới nhất lên đầu
      const photos = data.reverse().map(row => {
        let settings = {};
        try { settings = JSON.parse(row[2]); } catch(e) {}

        return {
          id: row[0],
          timestamp: new Date(row[1]).getTime(),
          settings: settings,
          dataUrl: row[3] // Ảnh Base64
        };
      });

      return responseJSON({ success: true, photos: photos });
    }

    // --- CASE 3: LẤY 1 ẢNH CHI TIẾT (GET PHOTO BY ID) ---
    if (action === 'get') {
      const id = e.parameter.id;
      const sheet = getOrCreateSheet(ss, SHEET_PHOTOS);
      const data = sheet.getDataRange().getValues();

      // Tìm dòng có ID tương ứng
      for (let i = data.length - 1; i >= 1; i--) {
        if (data[i][0] == id) {
          let settings = {};
          try { settings = JSON.parse(data[i][2]); } catch(e) {}

          const photo = {
            id: data[i][0],
            timestamp: new Date(data[i][1]).getTime(),
            settings: settings,
            dataUrl: data[i][3]
          };
          return responseJSON(photo); // Trả về object photo trực tiếp
        }
      }
      return responseJSON({ error: 'Not found' });
    }

    return responseJSON({ success: false, error: 'Invalid action in doGet' });

  } catch (error) {
    return responseJSON({ success: false, error: error.toString() });
  }
}

