      method: 'POST',
      body: JSON.stringify(payload),
      headers: { 'Content-Type': 'text/plain' } // Simple header to avoid preflight CORS
    });

    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const result = await response.json();

    if (result.success && result.id) {
        return result.id;
    } else {
        console.error("Lỗi từ Google Script:", result);
        return null;
