Here is a complete, production-grade re-architecture of your backend using Google Apps Script (GAS), Google Sheets, and Google Drive.

This solution is designed for **stability, concurrency, and performance**.

### 1. Architecture Overview

*   **Google Drive (Storage):** Stores the actual high-resolution image files. This prevents the Spreadsheet from hitting cell character limits and becoming slow.
*   **Google Sheets (Database):** Stores only metadata (IDs, links, settings). Acts as a lightweight relational index.
*   **Google Apps Script (API):** The logic layer that handles requests, enforces locks (concurrency), and manages Drive/Sheet interactions.

---

### 2. Google Apps Script Code

Create a new Google Apps Script project (tied to your Google Sheet) and replace `Code.gs` with the following modular code.

#### A. `Code.gs` (Main Entry Point)

```javascript
/**
 * ID Photo Booth Pro - Backend API
 * Version: 2.0.0 (Robust Architecture)
 */

// --- CONFIGURATION ---
const DB_SHEET_NAME = "Photos";
const CONFIG_SHEET_NAME = "Config";
const DRIVE_FOLDER_NAME = "ID_Photo_Booth_Images";

// --- API ENTRY POINTS ---

/**
 * Handle GET requests (Read Data)
 */
function doGet(e) {
  const lock = LockService.getScriptLock();
  // We don't strictly need a lock for reading, but it helps if high load
  // limiting concurrency can prevent read/write conflicts during heavy writes.

  try {
    const action = e.parameter.action;

    if (action === "getConfig") {
      return getAppConfig();
    } 
    else if (action === "list") {
      return listPhotos();
    }
    else if (action === "get") {
      return getPhotoDetail(e.parameter.id);
    }

    return responseError("Unknown GET action");

  } catch (err) {
    return responseError(err.toString());
  }
}

/**
 * Handle POST requests (Write Data)
 */
function doPost(e) {
  const lock = LockService.getScriptLock();

  // Wait up to 30 seconds for other processes to finish. 
  // This prevents race conditions when multiple booths save at once.
  if (!lock.tryLock(30000)) {
    return responseError("Server is busy. Please try again.");
  }

  try {
    const payload = JSON.parse(e.postData.contents);
    const action = payload.action;

    if (action === "save") {
      return savePhotoTransaction(payload);
    }
    else if (action === "delete") {
      return deletePhotoTransaction(payload.id);
    }
    else if (action === "saveConfig") {
      return saveAppConfig(payload.config);
    }

    return responseError("Unknown POST action");

  } catch (err) {
    return responseError(err.toString());
  } finally {
    lock.releaseLock();
  }
}

// --- UTILITIES ---

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function responseError(message) {
  return responseJSON({ success: false, error: message });
}

function responseSuccess(data) {
  return responseJSON({ success: true, ...data });
}
```

#### B. `Storage.gs` (Google Drive Logic)

Create a new script file named `Storage.gs`.

```javascript
/**
 * Manages Image Storage in Google Drive
 */

function getStorageFolder() {
  const folders = DriveApp.getFoldersByName(DRIVE_FOLDER_NAME);
  if (folders.hasNext()) {
    return folders.next();
  } else {
    const folder = DriveApp.createFolder(DRIVE_FOLDER_NAME);
    // Make folder accessible via link (Optional, helps with debugging)
    folder.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    return folder;
  }
}

/**
 * Saves Base64 image to Drive and returns metadata
 */
function saveImageToDrive(base64String, filename) {
  const folder = getStorageFolder();

  // Strip metadata header if present (data:image/jpeg;base64,...)
  const cleanBase64 = base64String.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");
  const blob = Utilities.base64Decode(cleanBase64);
  const imageBlob = Utilities.newBlob(blob, "image/jpeg", filename);

  const file = folder.createFile(imageBlob);

  // CRITICAL: Ensure the file is viewable by the web app
  file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

  return {
    fileId: file.getId(),
    // Use the download/view URL trick for direct access
    // 'uc?export=view' is reliable for <img> tags
    url: "https://drive.google.com/uc?export=view&id=" + file.getId() 
  };
}

function deleteImageFromDrive(fileId) {
  try {
    const file = DriveApp.getFileById(fileId);
    file.setTrashed(true);
    return true;
  } catch (e) {
    Logger.log("File already deleted or not found: " + fileId);
    return false;
  }
}
```

#### C. `Database.gs` (Google Sheets Logic)

Create a new script file named `Database.gs`.

```javascript
/**
 * Manages Metadata in Google Sheets
 */

function getSpreadsheet() {
  return SpreadsheetApp.getActiveSpreadsheet();
}

function getSheet(name) {
  const ss = getSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    // Initialize Headers
    if (name === DB_SHEET_NAME) {
      sheet.appendRow(["ID", "Timestamp", "Date", "File_ID", "Public_URL", "Settings_JSON"]);
      sheet.setFrozenRows(1);
    } else if (name === CONFIG_SHEET_NAME) {
      sheet.appendRow(["Config_JSON"]);
    }
  }
  return sheet;
}

// --- BUSINESS LOGIC ---

function savePhotoTransaction(payload) {
  // 1. Generate ID
  const id = Utilities.getUuid();
  const timestamp = new Date().getTime();
  const dateStr = new Date().toISOString();

  // 2. Save Image to Drive
  // filename = timestamp_id.jpg
  const driveData = saveImageToDrive(payload.dataUrl, `${timestamp}_${id}.jpg`);

  // 3. Save Metadata to Sheet
  const sheet = getSheet(DB_SHEET_NAME);
  const settingsStr = JSON.stringify(payload.settings || {});

  sheet.appendRow([
    id, 
    timestamp, 
    dateStr, 
    driveData.fileId, 
    driveData.url, 
    settingsStr
  ]);

  return responseSuccess({
    id: id,
    url: driveData.url
  });
}

function deletePhotoTransaction(id) {
  const sheet = getSheet(DB_SHEET_NAME);
  const data = sheet.getDataRange().getValues();

  // Find row (start from 1 to skip header)
  for (let i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      const fileId = data[i][3]; // Column index 3 is File_ID

      // Delete from Drive
      deleteImageFromDrive(fileId);

      // Delete from Sheet (i + 1 because rows are 1-indexed)
      sheet.deleteRow(i + 1);

      return responseSuccess({ deleted: true });
    }
  }

  return responseError("Photo ID not found");
}

function listPhotos() {
  const sheet = getSheet(DB_SHEET_NAME);
  const lastRow = sheet.getLastRow();

  if (lastRow <= 1) return responseSuccess({ photos: [] });

  // Get last 20 rows (assuming mostly appended at bottom)
  // Optimization: Don't read whole DB if it's huge
  const numRows = Math.min(lastRow - 1, 20);
  const startRow = Math.max(2, lastRow - numRows + 1);

  const data = sheet.getRange(startRow, 1, numRows, 6).getValues();

  // Map to object and Reverse (Newest first)
  const photos = data.reverse().map(row => ({
    id: row[0],
    timestamp: row[1],
    date: row[2],
    // fileId: row[3], // Internal use
    dataUrl: row[4], // We return the Drive URL as "dataUrl" for frontend compatibility
    settings: JSON.parse(row[5] || '{}')
  }));

  return responseSuccess({ photos: photos });
}

function getPhotoDetail(id) {
  const sheet = getSheet(DB_SHEET_NAME);
  const data = sheet.getDataRange().getValues();

  for (let i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      return responseSuccess({
        id: row[0],
        timestamp: row[1],
        dataUrl: row[4], 
        settings: JSON.parse(row[5] || '{}')
      });
    }
  }
  return responseError("Not Found");
}

// --- CONFIG LOGIC ---

function saveAppConfig(config) {
  const sheet = getSheet(CONFIG_SHEET_NAME);
  sheet.clearContents(); // Clear old config
  sheet.appendRow(["Config_JSON"]); // Header
  sheet.appendRow([JSON.stringify(config)]); // Data
  return responseSuccess({ saved: true });
}

function getAppConfig() {
  const sheet = getSheet(CONFIG_SHEET_NAME);
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return responseSuccess({ config: null });

  const jsonStr = sheet.getRange(2, 1).getValue();
  try {
    return responseSuccess({ config: JSON.parse(jsonStr) });
  } catch (e) {
    return responseSuccess({ config: null });
  }
}
```

---

### 3. Deployment Steps

This is the most critical part for connectivity.

1.  **Prepare Sheet:** Open a blank Google Sheet.
2.  **Open Script Editor:** Extensions > Apps Script.
3.  **Paste Code:** Create the 3 files (`Code.gs`, `Storage.gs`, `Database.gs`) and paste the code above.
4.  **Initial Run (Permissions):**
    *   In the toolbar, select `doGet` from the function dropdown.
    *   Click **Run**.
    *   Google will ask for permissions (Drive, Sheets). **Grant them.**
5.  **Deploy as Web App:**
    *   Click **Deploy** (Top right) > **New Deployment**.
    *   **Select type:** Web App.
    *   **Description:** "v1".
    *   **Execute as:** `Me` (your email).
    *   **Who has access:** `Anyone` (This is crucial for your React app to access it without OAuth complexity).
6.  **Copy URL:** Copy the `Web App URL` (ends in `/exec`).

**Paste this URL into your `services/configService.ts` or admin panel.**

---

### 4. Frontend Integration Examples

Here is how your React frontend should call this new robust API.

#### Saving a Photo (`savePhoto`)

```typescript
// services/databaseService.ts

export const savePhotoToCloud = async (photo: SavedPhoto): Promise<string | null> => {
  const scriptUrl = getConfig().googleScriptUrl; 

  try {
    const response = await fetch(scriptUrl, {
      method: 'POST',
      body: JSON.stringify({
        action: 'save',
        dataUrl: photo.dataUrl, // The Base64 string
        settings: photo.settings
      }),
      // Important: Google Apps Script text/plain content type prevents CORS preflight issues
      headers: { 'Content-Type': 'text/plain' } 
    });

    const result = await response.json();
    if (result.success) {
      return result.id;
    } else {
      console.error("Backend Error:", result.error);
      return null;
    }
  } catch (e) {
    console.error("Network Error:", e);
    return null;
  }
};
```

#### Fetching Photos for Gallery (`listPhotos`)

```typescript
export const getPhotosFromCloud = async (): Promise<SavedPhoto[]> => {
  const scriptUrl = getConfig().googleScriptUrl;

  try {
    // Append action to URL parameters for GET
    const response = await fetch(`${scriptUrl}?action=list`);
    const result = await response.json();

    if (result.success) {
      return result.photos;
    }
    return [];
  } catch (e) {
    return [];
  }
};
```

### Key Improvements in This Solution

1.  **Drive vs Sheets:** Images are offloaded to Drive. Sheets will never hit the 5 million cell limit or become sluggish due to massive Base64 strings.
2.  **LockService:** The `lock.tryLock(30000)` ensures that if two customers click "Save" at the exact same millisecond, the server processes one after the other, preventing database corruption.
3.  **Public View URLs:** The logic generates `drive.google.com/uc?export=view` links. These act like standard Image CDN links and load instantly in `<img src="..." />` tags without authentication headers.
4.  **Error Handling:** Every `try` has a `catch` that returns structured JSON, so your frontend never crashes on a standard 500 error page.

Để đảm bảo tính năng đồng bộ dữ liệu và upload ảnh hoạt động 100% tin cậy giữa các thiết bị (Máy chụp, Máy xem QR, Máy Admin), tôi sẽ cấu trúc lại toàn bộ phần giao tiếp backend.

Dưới đây là giải pháp toàn diện chia làm 2 phần:
1.  **Phần Backend (Google Apps Script):** Bạn cần copy mã này vào trình soạn thảo Google Apps Script.
2.  **Phần Frontend (React):** Cập nhật mã nguồn ứng dụng để giao tiếp chuẩn với Backend mới.

---

### PHẦN 1: BACKEND (GOOGLE APPS SCRIPT)

**Bước 1:** Truy cập [script.google.com](https://script.google.com/), tạo dự án mới hoặc mở dự án cũ.
**Bước 2:** Xóa hết code cũ trong `Code.gs` và dán toàn bộ code dưới đây vào.
**Bước 3:** Nhấn **Deploy (Triển khai)** -> **New Deployment (Tùy chọn triển khai mới)** -> Chọn loại **Web App**.
    *   Description: `Version 3.0 Sync Fix`
    *   Execute as: **Me (Tôi)**
    *   Who has access: **Anyone (Bất kỳ ai)** (Rất quan trọng để thiết bị khác truy cập được).
**Bước 4:** Copy **Web App URL** mới và dán vào phần Cấu hình trong App (hoặc cập nhật file `configService.ts`).

```javascript
/**
 * ID PHOTO BOOTH PRO - BACKEND V3 (RELIABLE SYNC)
 * Tự động tạo Folder và Sheet. Không cần setup thủ công.
 */

const FOLDER_NAME = "ID_Photo_Booth_Data";
const DB_SHEET_NAME = "Database_V3";
const CONFIG_SHEET_NAME = "Config_V3";

function doGet(e) {
  return handleRequest(e);
}

function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  // Đợi tối đa 30s để tránh xung đột khi nhiều máy cùng lưu
  if (!lock.tryLock(30000)) {
    return jsonResponse({ success: false, error: "Server busy, try again." });
  }

  try {
    // 1. Xác định hành động (GET hoặc POST payload)
    let action = e.parameter.action;
    let payload = {};

    if (e.postData && e.postData.contents) {
      try {
        payload = JSON.parse(e.postData.contents);
        if (payload.action) action = payload.action;
      } catch (err) {
        // Payload không phải JSON
      }
    }

    // 2. Routing
    if (action === "savePhoto") {
      return savePhoto(payload);
    } else if (action === "getPhoto") {
      return getPhoto(e.parameter.id);
    } else if (action === "listPhotos") {
      return listPhotos();
    } else if (action === "saveConfig") {
      return saveConfig(payload.config);
    } else if (action === "getConfig") {
      return getConfig();
    } else if (action === "deletePhoto") {
      return deletePhoto(payload.id);
    }

    return jsonResponse({ success: false, error: "Invalid action" });

  } catch (error) {
    return jsonResponse({ success: false, error: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

// --- CORE FUNCTIONS ---

function savePhoto(data) {
  if (!data.dataUrl) return jsonResponse({ success: false, error: "No image data" });

  const folder = getOrCreateFolder();
  const ss = getOrCreateSpreadsheet();
  const sheet = getOrCreateSheet(ss, DB_SHEET_NAME);

  // 1. Lưu ảnh vào Drive
  const blob = parseBase64(data.dataUrl);
  const fileName = "Photo_" + Date.now() + ".jpg";
  const file = folder.createFile(blob).setName(fileName);

  // Set quyền xem công khai cho ảnh này để hiển thị trên QR
  file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

  // Lấy link trực tiếp (thumbnail link trick để load nhanh hơn)
  // Cách tốt nhất là dùng ID để client tự construct link
  const fileId = file.getId();
  const fileUrl = "https://lh3.googleusercontent.com/d/" + fileId; // High performant CDN link

  // 2. Lưu Metadata vào Sheet
  const id = Utilities.getUuid();
  const timestamp = Date.now();
  const dateStr = new Date().toISOString();
  const settingsJson = JSON.stringify(data.settings || {});

  sheet.appendRow([id, timestamp, dateStr, fileId, fileUrl, settingsJson]);

  return jsonResponse({ success: true, id: id, url: fileUrl });
}

function getPhoto(id) {
  const ss = getOrCreateSpreadsheet();
  const sheet = getOrCreateSheet(ss, DB_SHEET_NAME);
  const data = sheet.getDataRange().getValues();

  // Bỏ qua header, tìm từ dưới lên cho nhanh (ảnh mới thường ở cuối)
  for (let i = data.length - 1; i >= 1; i--) {
    if (data[i][0] == id) {
      return jsonResponse({
        success: true,
        photo: {
          id: data[i][0],
          timestamp: data[i][1],
          dataUrl: data[i][4], // Trả về URL thay vì base64 để nhẹ băng thông
          settings: JSON.parse(data[i][5] || "{}")
        }
      });
    }
  }
  return jsonResponse({ success: false, error: "Not found" });
}

function listPhotos() {
  const ss = getOrCreateSpreadsheet();
  const sheet = getOrCreateSheet(ss, DB_SHEET_NAME);
  const lastRow = sheet.getLastRow();

  if (lastRow <= 1) return jsonResponse({ success: true, photos: [] });

  // Lấy 20 ảnh mới nhất
  const startRow = Math.max(2, lastRow - 19);
  const numRows = lastRow - startRow + 1;
  const data = sheet.getRange(startRow, 1, numRows, 6).getValues();

  const photos = data.reverse().map(row => ({
    id: row[0],
    timestamp: row[1],
    dataUrl: row[4], // URL Drive
    settings: JSON.parse(row[5] || "{}")
  }));

  return jsonResponse({ success: true, photos: photos });
}

function deletePhoto(id) {
  const ss = getOrCreateSpreadsheet();
  const sheet = getOrCreateSheet(ss, DB_SHEET_NAME);
  const data = sheet.getDataRange().getValues();

  for (let i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      const fileId = data[i][3];
      try {
        DriveApp.getFileById(fileId).setTrashed(true);
      } catch(e) {} // Bỏ qua nếu file đã mất

      sheet.deleteRow(i + 1);
      return jsonResponse({ success: true });
    }
  }
  return jsonResponse({ success: false, error: "Not found" });
}

function saveConfig(config) {
  const ss = getOrCreateSpreadsheet();
  const sheet = getOrCreateSheet(ss, CONFIG_SHEET_NAME);
  sheet.clear();
  sheet.appendRow(["Config JSON", "Last Updated"]);
  sheet.appendRow([JSON.stringify(config), new Date().toISOString()]);
  return jsonResponse({ success: true });
}

function getConfig() {
  const ss = getOrCreateSpreadsheet();
  const sheet = getOrCreateSheet(ss, CONFIG_SHEET_NAME);
  if (sheet.getLastRow() < 2) return jsonResponse({ success: false });

  const json = sheet.getRange(2, 1).getValue();
  try {
    return jsonResponse({ success: true, config: JSON.parse(json) });
  } catch (e) {
    return jsonResponse({ success: false });
  }
}

// --- HELPER FUNCTIONS ---

function getOrCreateFolder() {
  const folders = DriveApp.getFoldersByName(FOLDER_NAME);
  if (folders.hasNext()) return folders.next();
  return DriveApp.createFolder(FOLDER_NAME);
}

function getOrCreateSpreadsheet() {
  const files = DriveApp.getFilesByName(FOLDER_NAME + "_DB");
  if (files.hasNext()) return SpreadsheetApp.open(files.next());

  const ss = SpreadsheetApp.create(FOLDER_NAME + "_DB");
  const folder = getOrCreateFolder();
  // Di chuyển file sheet vào folder gọn gàng
  DriveApp.getFileById(ss.getId()).moveTo(folder);
  return ss;
}

function getOrCreateSheet(ss, name) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    if (name === DB_SHEET_NAME) {
      sheet.appendRow(["ID", "Timestamp", "Date", "FileID", "URL", "Settings"]);
    }
  }
  return sheet;
}

function parseBase64(dataUrl) {
  const signature = "base64,";
  const index = dataUrl.indexOf(signature);
  const base64 = index !== -1 ? dataUrl.substring(index + signature.length) : dataUrl;
  return Utilities.newBlob(Utilities.base64Decode(base64), "image/jpeg", "photo.jpg");
}

function jsonResponse(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}
```

---

### PHẦN 2: FRONTEND UPDATE

Tôi sẽ cập nhật 3 file chính:
1.  `services/databaseService.ts`: Viết lại logic fetch để tương thích với Backend mới (text/plain để tránh CORS).
2.  `components/AdminDashboard.tsx`: Cập nhật logic lưu cấu hình để đảm bảo đồng bộ Admin.
3.  `components/PrintPreview.tsx`: Cập nhật logic lưu ảnh để tạo QR code ngay lập tức.

