export default PrintPreview;

import { SavedPhoto, AppConfig } from "../types";
import { getConfig, saveConfig } from "./configService";

// --- HELPERS ---

const getScriptUrl = () => {
    const config = getConfig();
    return (config.googleScriptUrl || '').trim();
};

/**
 * Hàm gọi API chung (Universal Fetch Wrapper)
 * Xử lý CORS bằng cách dùng text/plain và parse JSON thủ công
 */
const callAppsScript = async (action: string, payload: any = {}): Promise<any> => {
    const url = getScriptUrl();
    if (!url) throw new Error("Chưa cấu hình Google Script URL trong Admin.");

    const fullPayload = {
        action,
        ...payload
    };

    try {
        const response = await fetch(url, {
            method: 'POST',
            // CRITICAL: Dùng text/plain để tránh Preflight OPTIONS request từ browser
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(fullPayload)
        });

        if (!response.ok) {
            throw new Error(`Server responded with ${response.status}`);
        }

        const data = await response.json();
        return data;

    } catch (error) {
        console.error(`API Call Error [${action}]:`, error);
        throw error;
    }
};

// --- PUBLIC API ---

/**
 * Lưu ảnh lên Cloud (Drive + Sheets)
 */
export const savePhotoToCloud = async (photo: SavedPhoto): Promise<string | null> => {
    try {
        const result = await callAppsScript('savePhoto', {
            dataUrl: photo.dataUrl,
            settings: photo.settings
        });

        if (result.success) {
            return result.id;
        } else {
            console.error("Save Failed:", result.error);
            return null;
        }
    } catch (e) {
        console.warn("Could not save photo to cloud:", e);
        return null;
    }
};

/**
 * Lấy danh sách ảnh (Chỉ URL, không lấy base64 để nhẹ)
 */
export const getPhotosFromCloud = async (): Promise<SavedPhoto[]> => {
    try {
        const result = await callAppsScript('listPhotos');
        if (result.success && Array.isArray(result.photos)) {
            return result.photos;
        }
        return [];
    } catch (e) {
        console.warn("Could not fetch photos:", e);
        return [];
    }
};

/**
 * Lấy chi tiết ảnh
 */
export const getPhotoById = async (id: string): Promise<SavedPhoto | null> => {
    try {
        const url = getScriptUrl();
        if (!url) return null;

        const fetchUrl = `${url}?action=getPhoto&id=${id}`;
        const response = await fetch(fetchUrl);
        const result = await response.json();

        if (result.success && result.photo) {
            return result.photo as SavedPhoto;
        }
        return null;
    } catch (e) {
        console.error("Get Photo Error:", e);
        return null;
    }
};

/**
 * Xóa ảnh khỏi Cloud
 */
export const deletePhotoFromCloud = async (id: string): Promise<boolean> => {
    try {
        const result = await callAppsScript('deletePhoto', { id });
        return result.success === true;
    } catch (e) {
        return false;
    }
};

/**
 * Lưu cấu hình Admin lên Cloud (Đồng bộ settings)
 * THÔNG MINH: Tự động upload Logo nếu là Base64 để tránh lỗi giới hạn ký tự Sheet
 */
export const saveAppConfigToCloud = async (config: AppConfig): Promise<boolean> => {
    try {
        // Tạo bản sao để không ảnh hưởng state hiện tại
        const configToSave = { ...config };

        // Kiểm tra xem logo có phải là ảnh Base64 (lớn) không
        if (configToSave.logoUrl && configToSave.logoUrl.startsWith('data:image')) {
            console.log("Detecting large Logo Base64. Uploading to Drive first...");

            // Tận dụng endpoint savePhoto để upload file
            const uploadResult = await callAppsScript('savePhoto', {
                dataUrl: configToSave.logoUrl,
                settings: { isSystemLogo: true, timestamp: Date.now() }
            });

            if (uploadResult.success && uploadResult.url) {
                console.log("Logo uploaded successfully:", uploadResult.url);
                // Thay thế Base64 bằng URL Drive ngắn gọn
                configToSave.logoUrl = uploadResult.url;
            } else {
                console.warn("Failed to upload logo image. Proceeding with Config save might fail.");
            }
        }

        // Lưu config (lúc này logoUrl đã là link ngắn)
        const result = await callAppsScript('saveConfig', { config: configToSave });
        return result.success === true;

    } catch (e) {
        console.error("Save Config Error:", e);
        return false;
    }
};

/**
 * Tải cấu hình từ Cloud về máy (Sync)
 */
export const getAppConfigFromCloud = async (): Promise<AppConfig | null> => {
    const url = getScriptUrl();
    if (!url) return null;

    try {
        const fetchUrl = `${url}?action=getConfig`;
        const response = await fetch(fetchUrl);
        const result = await response.json();

        if (result.success && result.config) {
            const currentLocal = getConfig();
            const remoteConfig = result.config;

            // Bảo vệ URL kết nối
            if (!remoteConfig.googleScriptUrl || remoteConfig.googleScriptUrl.trim() === '') {
                remoteConfig.googleScriptUrl = currentLocal.googleScriptUrl;
            }

            return remoteConfig;
        }
        return null;
    } catch (e) {
        return null;
    }
};

