                    </span>
                    <span>{settings.beauty.eyebrowIntensity}%</span>
                  </div>
                  <input type="range" min="0" max="100" step="20" value={settings.beauty.eyebrowIntensity} onChange={(e) => handleAiBeautyChange('eyebrowIntensity', Number(e.target.value))} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-gray-800" />
              </div>

              <hr className="border-gray-100" />

              {/* Lipstick */}
              <div>
                <label className="text-xs font-bold text-gray-600 block mb-2">Son môi</label>
