export const saveConfig = (config: AppConfig) => {
  // Save user settings
  const minimalStorage = {
      ...config,
      // We generally want to save the URL if the user manually changed it in Admin,
      // but to enforce the fix, getConfig will take precedence for the URL.
  };
  localStorage.setItem(CONFIG_KEY, JSON.stringify(minimalStorage));

  // Apply visual changes to current session immediately
  applyTheme(config.themeColorHex);
  updateFavicon(config.logoUrl);
};

export const getConfig = (): AppConfig => {
  const saved = localStorage.getItem(CONFIG_KEY);

  // Start with Defaults
  let config = { ...DEFAULT_CONFIG };

  if (saved) {
    try {
      const parsed = JSON.parse(saved);
      // Merge saved with default to ensure new fields (like hairColorOptions) exist
      config = {
          ...DEFAULT_CONFIG,
          ...parsed,
          // Ensure nested arrays are merged or defaulted if missing
          hairColorOptions: parsed.hairColorOptions || DEFAULT_CONFIG.hairColorOptions,
          lipstickOptions: parsed.lipstickOptions || DEFAULT_CONFIG.lipstickOptions
      };
    } catch (e) {
      // ignore error
    }
  }

  // FORCE NEW URL from Default Config
  // This ensures that even if the user has an old broken URL in localStorage,
  // the app will use the new working URL provided in the code update.
  config.googleScriptUrl = DEFAULT_CONFIG.googleScriptUrl;

  return config;
};

// Helper to convert Hex to RGB numbers string (e.g. "59 130 246") for Tailwind vars
const hexToRgb = (hex: string) => {
  let r = 0, g = 0, b = 0;
  // 3 digits
  if (hex.length === 4) {
    r = parseInt("0x" + hex[1] + hex[1]);
    g = parseInt("0x" + hex[2] + hex[2]);
    b = parseInt("0x" + hex[3] + hex[3]);
  } else if (hex.length === 7) {
    r = parseInt("0x" + hex[1] + hex[2]);
    g = parseInt("0x" + hex[3] + hex[4]);
    b = parseInt("0x" + hex[5] + hex[6]);
  }
  return `${r} ${g} ${b}`;
};

// Apply CSS variables to root
export const applyTheme = (hexColor: string) => {
  if (!hexColor) return;
  const rgb = hexToRgb(hexColor);
  const root = document.documentElement;

  root.style.setProperty('--brand-500', rgb);
  root.style.setProperty('--brand-600', rgb);
  root.style.setProperty('--brand-700', rgb);

  root.style.setProperty('--brand-50', rgb);
  root.style.setProperty('--brand-100', rgb);
  root.style.setProperty('--brand-200', rgb);
};

// Update Browser Tab Icon
export const updateFavicon = (logoUrl?: string) => {
  const link = document.getElementById('dynamic-favicon') as HTMLLinkElement;
  if (link) {
    // If logoUrl is present, use it. Otherwise use a default encoded SVG camera icon
    if (logoUrl) {
