    }

    // 1. Lưu cục bộ trước để đảm bảo Config Service có URL mới nhất
    saveConfig(form);
    onUpdateConfig(form);

    try {
        // 2. Thử đồng bộ lên Cloud
        const success = await saveAppConfigToCloud(form);

