              {/* NOTE: We only show processed layer clipped on top. Bottom is assumed original logic or blank if processed completely replaces it */}

              <img 
                src={originalImage} 
                alt="Before" 
                className="absolute inset-0 w-full h-full object-contain pointer-events-none" 
                style={{ backgroundColor: 'white' }}
              />

              {/* Top Image (Processed) - Clipped to reveal bottom */}
              {/* THE IMAGE ELEMENT HAS THE FILTERS, THE PARENT DIV HAS THE BACKGROUND */}
              <img 
                src={processedUrl} 
                alt="After" 
                className="absolute inset-0 w-full h-full object-contain pointer-events-none"
                style={{ 
                    filter: imageFilters,
                    // Use clip-path inset(top right bottom left) to reveal the underlying image
                    // We clip from the right side based on slider position
                    clipPath: `inset(0 ${100 - sliderPosition}% 0 0)`
                }}
              />

              {/* Slider Handle Line */}
              <div 
                className="absolute top-0 bottom-0 w-1 bg-white cursor-ew-resize z-20 shadow-[0_0_10px_rgba(0,0,0,0.3)]"
                style={{ left: `${sliderPosition}%` }}
              >
                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full shadow-xl flex items-center justify-center border border-gray-200">
                  <svg className="w-4 h-4 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 9l4-4 4 4m0 6l-4 4-4-4"></path></svg>
                </div>
              </div>

               {/* Labels */}
               <div className="absolute bottom-4 left-4 bg-black/50 text-white text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm pointer-events-none">TRƯỚC</div>
               <div className="absolute bottom-4 right-4 bg-brand-600/80 text-white text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm pointer-events-none">SAU</div>
            </div>
        ) : (
            // --- SIDE BY SIDE VIEW MODE ---
            <div className="flex gap-4 items-center justify-center h-[85vh] w-full px-4">
                 {/* Original */}
                 <div className="relative h-full flex-1 bg-white shadow-xl border-2 border-slate-200 rounded-lg overflow-hidden group">
                     <img src={originalImage} className="w-full h-full object-contain" alt="Original" />
                     <div className="absolute bottom-3 left-1/2 transform -translate-x-1/2 bg-black/60 text-white text-xs font-bold px-3 py-1 rounded-full backdrop-blur">Ảnh Gốc</div>
                 </div>

                 {/* Processed */}
                 <div 
                    className="relative h-full flex-1 shadow-xl border-2 border-brand-500 rounded-lg overflow-hidden group"
                    style={{ backgroundColor: getBackgroundColor() }}
                 >
                     <img src={processedUrl} className="w-full h-full object-contain" style={{ filter: imageFilters }} alt="Processed" />
                     <div className="absolute bottom-3 left-1/2 transform -translate-x-1/2 bg-brand-600/90 text-white text-xs font-bold px-3 py-1 rounded-full backdrop-blur">Kết quả</div>
                 </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default ImageEditor;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { PhotoSettings, PhotoSize, AppConfig, BackgroundType } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
  config: AppConfig;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved,
  onHome,
  config
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [realPhotoId, setRealPhotoId] = useState<string | null>(null);
  const [qrUrl, setQrUrl] = useState<string>('');

  // Stores the generated image URLs (Blobs) for printing
  const [sheetImages, setSheetImages] = useState<string[]>([]);
  const [isGeneratingSheets, setIsGeneratingSheets] = useState(false);

  // Layout Logic
  const getLayoutConfig = () => {
    if (size === PhotoSize.SIZE_3X4) {
      return { cols: 4, rows: 4, photoW_mm: 30, photoH_mm: 40, rotated: false, maxOnSheet: 16 };
    } else if (size === PhotoSize.SIZE_5X5) {
      return { cols: 2, rows: 3, photoW_mm: 50, photoH_mm: 50, rotated: false, maxOnSheet: 6 };
    } else {
      // 4x6 Default - Rotated
      return { cols: 2, rows: 4, photoW_mm: 60, photoH_mm: 40, rotated: true, maxOnSheet: 8 };
    }
  };

  const layout = getLayoutConfig();
  const totalPhotosNeeded = settings.printQuantity;
  const totalSheets = Math.ceil(totalPhotosNeeded / layout.maxOnSheet);

  // Helper to load image for Canvas
  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error(`Failed to load image`));
        img.src = src;
    });
  };

  // Helper to get background color hex
  const getBackgroundColor = () => {
      if (settings.background === BackgroundType.ORIGINAL) return null; // No fill needed, use original
      const bgConfig = config.backgroundConfig.find(b => b.type === settings.background);
      return bgConfig ? bgConfig.hexColor : '#ffffff';
  };

  // --- CORE LOGIC: Generate Sheet Image via Canvas ---
  const generateSheetCanvas = async (sheetIdx: number, photoImg: HTMLImageElement, logoImg: HTMLImageElement | null, qrImg: HTMLImageElement | null): Promise<string> => {
        const DPI = 300;
        const MM_TO_PX = DPI / 25.4;
        const SHEET_W = Math.ceil(130 * MM_TO_PX);
        const SHEET_H = Math.ceil(180 * MM_TO_PX);

        const canvas = document.createElement('canvas');
        canvas.width = SHEET_W;
        canvas.height = SHEET_H;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error("Canvas init failed");

        // 1. Fill White Background (Toàn bộ trang giấy in)
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Draw Photos
        const startIdx = sheetIdx * layout.maxOnSheet;
        const endIdx = Math.min(startIdx + layout.maxOnSheet, totalPhotosNeeded);
        const countForSheet = endIdx - startIdx;

        const cellW = layout.photoW_mm * MM_TO_PX;
        const cellH = layout.photoH_mm * MM_TO_PX;
        const gridW = layout.cols * cellW;
        const startX = (canvas.width - gridW) / 2;
        const startY = 5 * MM_TO_PX; 

        const photoBgColor = getBackgroundColor();

        for (let i = 0; i < countForSheet; i++) {
            const r = Math.floor(i / layout.cols);
            const c = i % layout.cols;
            const x = startX + c * cellW;
            const y = startY + r * cellH;

            ctx.save();
            ctx.beginPath();
            ctx.rect(x, y, cellW, cellH);
            ctx.clip();

            // DRAW BACKGROUND COLOR FIRST (Since image is now Transparent PNG)
            if (photoBgColor) {
                ctx.fillStyle = photoBgColor;
                ctx.fillRect(x, y, cellW, cellH);
            }

            if (layout.rotated) {
                const cx = x + cellW / 2;
                const cy = y + cellH / 2;
                ctx.translate(cx, cy);
                ctx.rotate(-90 * Math.PI / 180);
                // When rotated, width becomes height visually
                // Draw Image centered
                ctx.drawImage(photoImg, -cellH/2, -cellW/2, cellH, cellW); 
            } else {
                ctx.drawImage(photoImg, x, y, cellW, cellH);
            }
            ctx.restore();

            // Dashed Cutting Lines
            ctx.strokeStyle = '#d1d5db';
            ctx.lineWidth = 1;
            ctx.setLineDash([15, 15]);
            ctx.strokeRect(x, y, cellW, cellH);
        }

        // 3. Draw Footer
        const footerH = 15 * MM_TO_PX; 
        const footerY = canvas.height - footerH;

        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, footerY, canvas.width, footerH);

        ctx.beginPath();
        ctx.moveTo(0, footerY);
        ctx.lineTo(canvas.width, footerY);
        ctx.strokeStyle = '#000000';
        ctx.lineWidth = 2;
        ctx.setLineDash([]);
        ctx.stroke();

        const padding = 5 * MM_TO_PX;
        const contentY = footerY + footerH / 2;
        let leftOffset = padding;

        // --- Logo ---
        if (logoImg) {
            const logoH = 10 * MM_TO_PX;
            const scale = logoH / logoImg.height;
            const logoW = logoImg.width * scale;
            const logoY = contentY - logoH / 2;

            ctx.drawImage(logoImg, leftOffset, logoY, logoW, logoH);
            leftOffset += logoW + (3 * MM_TO_PX);
        }

        // --- Shop Name & Info ---
        ctx.textAlign = 'left';

        ctx.fillStyle = '#000000';
        const nameSize = 5 * MM_TO_PX;
        ctx.font = `bold ${nameSize}px sans-serif`;
        ctx.textBaseline = 'bottom';
        const shopName = config?.shopName || "ID Photo Booth";
        ctx.fillText(shopName, leftOffset, contentY - (0.5 * MM_TO_PX));

        ctx.fillStyle = '#4b5563'; 
        const infoSize = 3.5 * MM_TO_PX;
        ctx.font = `${infoSize}px sans-serif`;
        ctx.textBaseline = 'top'; 
        const dateStr = new Date().toLocaleDateString('vi-VN');
        const footerText = config?.printFooterText || "Ảnh thẻ lấy ngay";
        ctx.fillText(`${footerText} | Sheet ${sheetIdx + 1}/${totalSheets} | ${dateStr}`, leftOffset, contentY + (0.5 * MM_TO_PX));

        // --- QR Code ---
        if (qrImg) {
            const qrSize = 12 * MM_TO_PX; 
            const qrX = canvas.width - padding - qrSize;
            const qrY = contentY - qrSize / 2;

            ctx.drawImage(qrImg, qrX, qrY, qrSize, qrSize);

            // Mini Logo inside QR
            if (logoImg) {
                const centerLogoSize = qrSize * 0.25; 
                const centerX = qrX + (qrSize - centerLogoSize) / 2;
                const centerY = qrY + (qrSize - centerLogoSize) / 2;

                ctx.fillStyle = '#ffffff';
                ctx.fillRect(centerX - 1, centerY - 1, centerLogoSize + 2, centerLogoSize + 2);
                ctx.drawImage(logoImg, centerX, centerY, centerLogoSize, centerLogoSize);
            }
        }

        return canvas.toDataURL('image/png');
  };

  // Generate Sheets when dependencies are ready
  useEffect(() => {
     const generateAllSheets = async () => {
         // Chờ đến khi có QR URL (tức là đã lưu cloud thành công)
         if (!qrUrl) return; 

         setIsGeneratingSheets(true);

         try {
             const [photoImg, logoImg, qrImg] = await Promise.all([
                 loadImage(processedImage),
                 config.logoUrl ? loadImage(config.logoUrl).catch(() => null) : Promise.resolve(null),
                 loadImage(qrUrl).catch(() => null)
             ]);

             const generatedSheets: string[] = [];
             for (let i = 0; i < totalSheets; i++) {
                 const dataUrl = await generateSheetCanvas(i, photoImg, logoImg, qrImg);
                 generatedSheets.push(dataUrl);
             }
             setSheetImages(generatedSheets);

         } catch (e) {
             console.error("Failed to generate print sheets", e);
         } finally {
             setIsGeneratingSheets(false);
         }
     };

     generateAllSheets();
  }, [qrUrl, processedImage, totalSheets, config]);


  // Auto Save to Cloud on Mount
  useEffect(() => {
    const autoSave = async () => {
      setIsSaving(true);

      const dbId = await savePhotoToCloud({
        id: 'temp', // ID sẽ được tạo bởi Server
        dataUrl: processedImage,
        timestamp: Date.now(),
        settings: settings
      });

      if (dbId) {
        setRealPhotoId(dbId);

        // Dynamic Base URL check
        let baseUrl = window.location.href.split('?')[0];
        baseUrl = baseUrl.replace(/\/$/, "");

        // Link to view the photo
        const viewerUrl = `${baseUrl}?photoId=${dbId}`;
        console.log("Viewer URL Generated:", viewerUrl);

        // Tạo QR Code High Error Correction (H)
        setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(viewerUrl)}&color=000000&bgcolor=FFFFFF&margin=0&ecc=H`);
      } else {
          console.error("Failed to save to cloud");
          alert("Không thể lưu ảnh lên Cloud. Kiểm tra kết nối Internet.");
      }
      setIsSaving(false);
    };

    if (!realPhotoId) {
        autoSave();
    }
  }, []); 

  const handlePrint = () => {
    if (sheetImages.length === 0) {
        alert("Đang chuẩn bị file in. Vui lòng đợi trong giây lát...");
        return;
    }
    window.print();
  };

  const handleDownloadSheets = () => {
    if (sheetImages.length === 0) {
        alert("Đang tạo file, vui lòng đợi...");
        return;
    }
    sheetImages.forEach((dataUrl, idx) => {
        const link = document.createElement('a');
        link.href = dataUrl;
        link.download = `Print-Sheet-${idx + 1}-13x18.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    });
  };

  const printPortalContent = (
     <div className="print-portal-root">
         {sheetImages.map((src, idx) => (
             <div key={idx} className="sheet-page">
                 <img src={src} style={{ width: '100%', height: '100%', display: 'block' }} alt={`Print Sheet ${idx+1}`} />
             </div>
         ))}
     </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-100 relative">

      {document.getElementById('print-mount') && createPortal(printPortalContent, document.getElementById('print-mount')!)}

      <header className="bg-white shadow-sm p-4 flex justify-between items-center z-20">
        <h1 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
          <svg className="w-6 h-6 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
          Print Preview 
        </h1>
        <div className="flex gap-3">
          <button onClick={onBack} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg transition">Quay lại</button>
        </div>
      </header>

      <div className="flex-1 overflow-hidden flex justify-center items-start gap-8 p-8 bg-slate-100">

        {/* SHEETS CONTAINER */}
        <div className="h-full overflow-auto flex flex-col items-center justify-start scrollbar-hide pb-20">
            {sheetImages.length > 0 ? (
                sheetImages.map((src, idx) => (
                    <div 
                        key={idx}
                        className="bg-white shadow-2xl mb-8 transform transition hover:scale-[1.01]"
                        style={{ width: '130mm', height: '180mm' }}
                    >
                        <img src={src} className="w-full h-full object-contain" alt={`Preview ${idx}`} />
                    </div>
                ))
            ) : (
                <div className="w-[130mm] h-[180mm] bg-white shadow-xl flex flex-col items-center justify-center gap-4">
                    <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin"></div>
                    <p className="text-gray-400 text-sm font-bold animate-pulse">
                        {isSaving ? 'Đang lưu Cloud...' : 'Đang tạo QR & File in...'}
                    </p>
                </div>
            )}
        </div>

        {/* SIDEBAR */}
        <div className="w-80 bg-white p-6 rounded-2xl shadow-xl flex flex-col gap-6 h-fit sticky top-6">

          <div>
            <div className="flex justify-between items-center mb-4">
               <h3 className="font-bold text-gray-800">Thao tác chính</h3>
               <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded-full font-bold">{settings.printQuantity} ảnh</span>
            </div>

            <button 
              onClick={handleDownloadSheets}
              disabled={sheetImages.length === 0}
              className="group w-full py-3 bg-white border-2 border-brand-200 text-brand-700 hover:bg-brand-50 hover:border-brand-300 rounded-xl font-bold shadow-sm transition-all flex items-center justify-center gap-2 mb-3 disabled:opacity-50"
            >
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
               <span>Tải File In (13x18)</span>
            </button>

            <button 
              onClick={handlePrint}
              disabled={isSaving || sheetImages.length === 0}
              className="group w-full py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition-all flex flex-col items-center justify-center gap-1 mb-3 disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              <div className="flex items-center gap-2">
                {sheetImages.length === 0 ? (
                    <div className="w-5 h-5 border-2 border-white/50 border-t-white rounded-full animate-spin"></div>
                ) : (
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                )}
                <span>{isSaving ? 'ĐANG LƯU...' : sheetImages.length === 0 ? 'ĐANG XỬ LÝ...' : 'IN NGAY'}</span>
              </div>
              <span className="text-[10px] opacity-80 font-normal">Khổ 13x18cm (Ctrl + P)</span>
            </button>

            <div className="bg-yellow-50 p-3 rounded-lg border border-yellow-200 text-xs text-yellow-800 mb-4">
                <strong>Lưu ý in:</strong> Chọn khổ giấy "13x18cm" hoặc "5x7in". Tắt "Header/Footer" trong hộp thoại in.
            </div>

            <div className="bg-slate-50 border border-slate-200 rounded-xl p-3 text-center">
               <h3 className="font-bold text-gray-800 mb-2 text-xs uppercase tracking-wider">Mã QR Tải Ảnh</h3>
               {qrUrl ? (
                   <div className="flex flex-col items-center">
                       <div className="relative w-28 h-28 mb-2">
                           <img src={qrUrl} alt="QR Big" className="w-full h-full mix-blend-multiply" />
                            {config.logoUrl && (
                                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-7 h-7 bg-white rounded-full p-0.5 border border-gray-100 shadow-sm flex items-center justify-center">
                                    <img src={config.logoUrl} className="w-full h-full object-contain rounded-full" alt="Mini Logo" />
                                </div>
                            )}
                       </div>
                       <p className="text-[10px] text-gray-500">Quét để tải ảnh gốc</p>
                       <p className="text-[9px] font-mono text-gray-400 mt-1">ID: {realPhotoId}</p>
                   </div>
               ) : (
                   <div className="h-28 flex items-center justify-center text-xs text-gray-400">
                       <div className="flex flex-col items-center gap-2">
                           <div className="w-5 h-5 border-2 border-gray-300 border-t-gray-600 rounded-full animate-spin"></div>
                           <span>Đang tạo QR...</span>
                       </div>
