                <div className="space-y-4 px-2">
                   <div>
                      <div className="flex justify-between text-xs font-bold text-gray-500 mb-1"><span>Độ sáng</span><span>{settings.beauty.lighting}</span></div>
                      <input type="range" min="-50" max="50" step="5" value={settings.beauty.lighting} onChange={(e) => handleClientBeautyChange('lighting', Number(e.target.value))} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-yellow-500" />
                   </div>
                   <div>
                      <div className="flex justify-between text-xs font-bold text-gray-500 mb-1"><span>Tương phản</span><span>{settings.beauty.contrast}</span></div>
                      <input type="range" min="-50" max="50" step="5" value={settings.beauty.contrast} onChange={(e) => handleClientBeautyChange('contrast', Number(e.target.value))} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-gray-600" />
                   </div>
                </div>
              </div>
              <hr className="border-gray-100" />

              {/* Skin Tone */}
              <div>
                <h3 className="text-sm font-bold text-gray-800 mb-3 flex items-center gap-2"><svg className="w-4 h-4 text-pink-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg> Tông màu da</h3>
                <div className="grid grid-cols-4 gap-2 mb-4">
                  {SkinToneOptions.map(tone => (
