                      <div className="w-6 h-6 rounded-full border shadow-sm" style={{ backgroundColor: tone.color }}></div>
                      <span className="text-[9px] font-bold text-gray-600">{tone.label}</span>
                    </button>
                  ))}
                </div>
                <input type="range" min="0" max="100" step="10" value={settings.beauty.skinToneIntensity} onChange={(e) => handleClientBeautyChange('skinToneIntensity', Number(e.target.value))} className="w-full h-2 bg-amber-100 rounded-lg appearance-none cursor-pointer accent-amber-600" />
              </div>
            </div>
          )}

          {/* MAKEUP TAB (AI) */}
          {activeTab === 'makeup' && (
            <div className="space-y-6 animate-fadeIn pb-24">

              {/* --- SKIN SMOOTHING (MOVED HERE) --- */}
              <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                  <h3 className="text-sm font-bold text-gray-800 mb-3 flex items-center gap-2">
                     <div className="bg-purple-500 text-white p-1 rounded-md">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z"></path></svg>
                     </div>
                     Làm mịn da (AI)
                  </h3>

                  <div className="mb-2">
                    <div className="flex justify-between text-xs font-bold text-gray-600 mb-2">
                        <span>
                            {settings.beauty.smoothSkin === 0 ? 'Tắt' : 
                             settings.beauty.smoothSkin <= 30 ? 'Tự nhiên (Khử dầu)' :
                             settings.beauty.smoothSkin <= 70 ? 'Chân dung (Mịn vừa)' : 
                             'Mịn ảo (Porcelain)'}
                        </span>
                        <span>{settings.beauty.smoothSkin}%</span>
                    </div>
                    {/* Gradient Slider Track */}
                    <div className="relative w-full h-2 bg-gray-200 rounded-lg">
                        <div className="absolute inset-0 rounded-lg bg-gradient-to-r from-gray-200 via-purple-300 to-purple-600 opacity-50"></div>
                        <input 
                            type="range" 
                            min="0" 
